  function getInnovationList($currentTab = 'all', $post_val) {
  	$options = $this->make_filter($currentTab, $post_val);
  	if (isset($_GET['iDisplayStart']) && $_GET['iDisplayLength'] != '-1') {
  		$options['offset'] = intval($_GET['iDisplayStart']);
  		$options['num'] = intval($_GET['iDisplayLength']);
  	}
  	$options['currentTab'] = $currentTab;

  	$data['innovationList'] = $this->Minnovation->getLimitRecords_portfolio($options);
  	if (isset($this->session->userdata['user_id'])) {
  		echo json_encode($data['innovationList']);
  	} else {
  		echo json_encode($data['error'] = "LoginError");
  	}
  }

  public function pendinginputlist($id = '') {
  	if ($id != '')
  		check_partner_privilege($id);
  	$status = 1;
  	$data['search_value'] = $search_value = (isset($_POST['search_value'])) ? $_POST['search_value'] : '';
  	$option['id'] = $c_option['inv_id'] = $data['innovation_id'] = $id;
  	$emp_id = $option1['associate_employee'] = $this->session->userdata['emp_number'];

  	$partner_id = $this->session->userdata('partner_id');
  	$data['fin_year'] = $this->Mportfolio->getAllFinancialYear($partner_id);
  	if ($data['fin_year'][0]['fin_year'] != '') {
  		foreach ($data['fin_year'] as $fy) {
  			if ($fy['status'] == 1) {
  				$f_year = $fy['fin_year'];
  			}
  		}
  	} else {
  		$f_year = date('Y');
  	}

  	$cur_month = date('M');
  	$getmonth = $this->month();
  	$actualMonth = $this->actual_month();
  	$arr = array_search($cur_month, $getmonth);

  	for ($i = ($arr - 1); $i >= 0; $i--) {
  		$monthName[] = $getmonth[$i];
  	}
  	$pends_innov = array();

  	$status1 = 1;
  	$data['config_listing'] = $config_list = $this->Mportfolio->getListingDetails('assign_associate', $option1, $status1);
  	$plan_tables = array('plan_updates', 'plan_sales', 'plan_channel', 'plan_pipeline', 'plan_finance', 'plan_loans', 'plan_fundraise', 'plan_vif_funding', 'plan_impact', 'plan_team_hiring', 'plan_mentor', 'plan_tap', 'plan_partnerships', 'plan_dp', 'plan_board_meetings');
  	foreach ($plan_tables as $tables) {
  		$pends = array();
  		$table_inv = $this->Mportfolio->getPendingTablescnt($tables, $f_year);
//        $exist_inv = $this->Mportfolio->getPendingExistInv($f_year);
//        echo '<pre>';
  		foreach ($table_inv as $tbl) {
  			$pends[$tbl['inv_id']] += 1;
  		}

  		foreach ($pends as $allpends => $pendval) {
  			if ($pendval < count($monthName)) {
  				$pends_innov[] = $allpends;
  			}
  		}
  	}
  	$result_inv = array_values(array_unique($pends_innov));
  	if (count($result_inv) > 0) {
  		$exist_inv = implode(',', $result_inv);
  		$pendingplan_inv = $this->Mportfolio->getPendingPlansInv($f_year, $exist_inv);
  		$config_inv = implode(',', $pendingplan_inv[0]['innovation']);
  		$company_chk = $this->Mportfolio->getCompanyInvs($config_inv);
  		foreach ($company_chk as $lists) {
  			$listing[] = $lists['innovation'];
  		}
  		$innov_id = rtrim(implode(',', $listing), ',');
  	} else {
  		$innov_id = '';
  	}
//        $plan_inv = $this->Mportfolio->getPlanInv();
  	$data['listing'] = $this->Mportfolio->getPendingInputList('', '', $search_value, $innov_id, $status);
  	$this->load->vars($data);
  	$this->load->view('portfolio/pendinginputlist');
  }

