  	$data['user_list'] = $this->Muser->getUsersList($userSetup1['abi'], $branch_id);

  	$userSetup = $this->Mmaster->getUserSetup();
  	$data['usersList'] = $this->Muser->getUsersList($userSetup['abi']);

  	$this->load->vars($data);
  	$this->load->view('portfolio/deals_list');
  }

  public function alldeals() { 
  	$data['copy_id'] = (isset($_POST['copy_id'])) ? $_POST['copy_id'] : '';
  	$data['name_of_enterprise'] = (isset($_POST['name_of_enterprise'])) ? $_POST['name_of_enterprise'] : '';
  	$data['name_of_entrepreneur'] = (isset($_POST['name_of_entrepreneur'])) ? $_POST['name_of_entrepreneur'] : '';
  	$data['source_type'] = (isset($_POST['source_type'])) ? $_POST['source_type'] : '';
  	$data['sector'] = (isset($_POST['sector'])) ? $_POST['sector'] : '';

  	$set_program = '';
  	if ($this->session->userdata('role_id') == '4') {
  		$custom_program = $this->session->userdata('programAccess');
  		$split_program = explode(',', $custom_program);
  		if (count($custom_program) == 1) {
  			$set_program = $split_program[0];
  		}
  	}

  	$data['program'] = (isset($_POST['program'])) ? $_POST['program'] : $set_program;
  	$data['stage'] = (isset($_POST['stage'])) ? $_POST['stage'] : '';
  	$data['status'] = (isset($_POST['status'])) ? $_POST['status'] : '';
  	$data['created_date'] = (isset($_POST['created_date'])) ? $_POST['created_date'] : '';
  	$data['created_date_to'] = (isset($_POST['created_date_to'])) ? $_POST['created_date_to'] : '';
  	$data['submitted_date'] = (isset($_POST['submitted_date'])) ? $_POST['submitted_date'] : '';
  	$data['submitted_date_to'] = (isset($_POST['submitted_date_to'])) ? $_POST['submitted_date_to'] : '';
  	$data['geography'] = (isset($_POST['geography'])) ? $_POST['geography'] : '';
  	$data['opertaion_stage'] = (isset($_POST['opertaion_stage'])) ? $_POST['opertaion_stage'] : '';
  	$data['enterprise_stage'] = (isset($_POST['enterprise_stage'])) ? $_POST['enterprise_stage'] : '';
  	$data['city'] = (isset($_POST['city'])) ? $_POST['city'] : '';
  	$data['lis'] = (isset($_POST['lis'])) ? $_POST['lis'] : '';
  	$data['donor_fit'] = (isset($_POST['donor_fit'])) ? $_POST['donor_fit'] : '';
  	$data['assigned_incharge'] = (isset($_POST['assigned_incharge'])) ? $_POST['assigned_incharge'] : '';
  	$data['email'] = (isset($_POST['email'])) ? $_POST['email'] : '';
  	$data['mobile'] = (isset($_POST['mobile'])) ? $_POST['mobile'] : '';
  	$data['branch_name'] = (isset($_POST['branch_name'])) ? ($_POST['branch_name']) : $this->session->userdata('partner_id');
  	$this->session->branchdetails['admin_branch'] = !empty($this->session->branchdetails['admin_branch']) ? $this->session->branchdetails['admin_branch'] : $data['branch_name'];

  	/* for export */
        // if ($currentTab == '') {
        //     if (in_array($this->session->userdata('user_type'), array('superadmin', 'admin', 'ceo', 'cio')))
        //         $currentTab = 'all';
        //     if ($this->session->userdata('user_name') == 'Altacit')
        //         $currentTab = 'identified';
        //     else
        //         $currentTab = 'assigned';
        // }
        // $data['currentTab'] = $currentTab;
  	$options = $this->make_filter('', $data);
	
  	if ($this->input->post('txtExport')) {
  		$this->innovation_download($options);
  	}

  	if ($this->input->post('txtExport_all')) {
  		$this->innovation_export($options);
  	}

  	/* export ends */

  	$data['stage_list'] = $this->Minnovation->getInnvationStage();
  	if ($this->session->userdata['role_id'] == '4' && $this->session->userdata['independent_shortlist'] == '1') {
  		$data['status_list'] = $this->Minnovation->getIndependentStatus();
  	} else {
  		$data['status_list'] = $this->Minnovation->getInnvationStatus();
  	}
  	$data['donor_list'] = $this->Minnovation->getDonorFit();
  	$data['branch'] = $this->Mmaster->getBranch();
  	$data['cpagetitle'] = "All Deals from Partner";
  	$data['deals_tab'] = 'alldeals';

  	$branch_id = $this->session->userdata('partner_id');
  	$accessto = $this->session->userdata['accessTo'];
  	$data['partnerS'] = $this->Mportfolio->getPartnerDetails($accessto, $branch_id);
  	$userSetup1 = $this->Mmaster->getUserSetup_branch($branch_id);
  	$data['user_list'] = $this->Muser->getUsersList($userSetup1['abi'], $branch_id);

  	$userSetup = $this->Mmaster->getUserSetup();
  	$data['usersList'] = $this->Muser->getUsersList($userSetup['abi']);

  	$this->load->vars($data);
  	$this->load->view('portfolio/deals_list');
  }

