    /* deals by user status */

    function deals_user_export() {
    	if ($id != '')
    		check_partner_privilege($id);
    	$this->load->library('Excel');
    	$objPHPExcel = new PHPExcel();
    	$objPHPExcel->getProperties()->setCreator("Villgro")
    	->setLastModifiedBy("Villgro")
    	->setTitle("Documents Master List")
    	->setSubject("Documents Master List")
    	->setDescription("Documents Master List")
    	->setKeywords("office 2007 openxml php")
    	->setCategory("Documents Master List");
    	$currmonth = date('M');

    	$styletitle = array(
    		'font' => array(
    			'bold' => true,
    			'color' => array('rgb' => '000000'),
    			'size' => 11,
    			'name' => 'Times New Roman',
    		),
    	);



    	$objPHPExcel->setActiveSheetIndex(0);
    	$objPHPExcel->getActiveSheet()->setTitle('Plan');

    	$rowHead = array('A' => 'Innovation_id', 'B' => 'Name_of_Entrepreneur', 'C' => 'Name_of_Enterprise', 'D' => 'Email', 'E' => 'Mobile_number', 'F' => 'Stage', 'G' => 'Status', 'H' => 'State_Name', 'I' => 'City_Name', 'J' => 'Program', 'K' => 'Sector', 'L' => 'Sub_sector', 'M' => 'Stage_of_operation', 'N' => 'Asssigned_To', 'O' => 'Submitted_Date', 'P' => 'Shortlist_name', 'Q' => 'Shortlist_Comments', 'R' => 'Shortlist_status', 'S' => 'Shortlist_Date');


        // $objPHPExcel->getActiveSheet()->getColumnDimension('A')->setWidth(30);
        // $objPHPExcel->getActiveSheet()->getColumnDimension('B')->setWidth(30);
    	foreach ($rowHead as $rowcol => $rowval) {
    		$objPHPExcel->getActiveSheet()->setCellValue($rowcol . '1', $rowval);
    	}
    	$row_no = 2;

    	$requestData = $_POST;
    	$data['deals_tab'] = (isset($_POST['deals_tab'])) ? $_POST['deals_tab'] : '';
    	$data['copy_id'] = (isset($_POST['copy_id'])) ? $_POST['copy_id'] : '';
    	$data['name_of_enterprise'] = (isset($_POST['name_of_enterprise'])) ? $_POST['name_of_enterprise'] : '';
    	$data['name_of_entrepreneur'] = (isset($_POST['name_of_entrepreneur'])) ? $_POST['name_of_entrepreneur'] : '';
    	$data['source_type'] = (isset($_POST['source_type'])) ? $_POST['source_type'] : '';
    	$data['sector'] = (isset($_POST['sector'])) ? $_POST['sector'] : '';
    	$data['program'] = (isset($_POST['program'])) ? $_POST['program'] : '';
    	$data['stage'] = (isset($_POST['stage'])) ? $_POST['stage'] : '';
    	$data['status'] = (isset($_POST['status'])) ? $_POST['status'] : '';
    	$data['created_date'] = (isset($_POST['created_date'])) ? $_POST['created_date'] : '';
    	$data['created_date_to'] = (isset($_POST['created_date_to'])) ? $_POST['created_date_to'] : '';
    	$data['submitted_date'] = (isset($_POST['submitted_date'])) ? $_POST['submitted_date'] : '';
    	$data['submitted_date_to'] = (isset($_POST['submitted_date_to'])) ? $_POST['submitted_date_to'] : '';
    	$data['geography'] = (isset($_POST['geography'])) ? $_POST['geography'] : '';
    	$data['opertaion_stage'] = (isset($_POST['opertaion_stage'])) ? $_POST['opertaion_stage'] : '';
    	$data['enterprise_stage'] = (isset($_POST['enterprise_stage'])) ? $_POST['enterprise_stage'] : '';
    	$data['city'] = (isset($_POST['city'])) ? $_POST['city'] : '';
    	$data['lis'] = (isset($_POST['lis'])) ? $_POST['lis'] : '';
    	$data['donor_fit'] = (isset($_POST['donor_fit'])) ? $_POST['donor_fit'] : '';
    	$data['assigned_incharge'] = (isset($_POST['assigned_incharge'])) ? $_POST['assigned_incharge'] : '';
    	$data['email'] = (isset($_POST['email'])) ? $_POST['email'] : '';
    	$data['mobile'] = (isset($_POST['mobile'])) ? $_POST['mobile'] : '';
    	$data['branch_name'] = (isset($_POST['branch_name'])) ? ($_POST['branch_name']) : $this->session->userdata('partner_id');
    	$this->session->branchdetails['admin_branch'] = !empty($this->session->branchdetails['admin_branch']) ? $this->session->branchdetails['admin_branch'] : $data['branch_name'];

    	$check_type = (isset($_POST['deals_tab'])) ? $_POST['deals_tab'] : '';
    	if ($check_type == 'mydeals') {
    		$this->load->model('Mincharge');
    		$innovation = $this->Mincharge->getAssociateInnovation($this->session->userdata('emp_number'));
    		$innovation = (count($innovation)) ? $innovation : array();
    		$data['associate'] = $innovation;
    	}

    	$totalrows = $this->Mportfolio->getDTDealsCount($data, $columns, $requestData);
    	$query = $this->Mportfolio->getDTDealsDetails($requestData['length'], $requestData['start'], $data, $columns, $requestData);
        // print_r($query);
        // die;

    	$totalFiltered = $totalrows;
    	$totalData = count($query);
    	$data = array();
    	$i = $requestData['start'] + 1;

    	foreach ($query as $row) {
    		$copy = $row['copy_partner_id'];
    		$copyud = substr($copy, 1);
    		$sql = "SELECT partner_name as branch_name FROM hr_partner_type where id = " . $copyud . "";
    		$result = mysqli_query($sql);
    		$row1 = mysqli_fetch_array($result);

    		$asArray = array();
    		$associate = $this->Mincharge->getAssociate(array('innovation' => $row['id'], 'active' => 'Active'));

    		foreach ($associate as $as):
    			$asArray[] = $as['emp_name'];
    		endforeach;
    		$row['associate_emp_name'] = implode(', ', $asArray);

    		$branch_name = $row['branch_name'];
    		if ($row['copy_partner_id'] == '') {
    			$inv_id = $row['id'] . "_" . $row['partner_id'] . "_" . $row['partner_count'];
    		} else {
    			$inv_id = $row['id'] . "_" . $row['copy_partner_id'] . "_" . $row['partner_count'];
    		}
    		$objPHPExcel->getActiveSheet()->setCellValue('A' . $row_no, $inv_id);
    		$er = $row['name_of_entrepreneur'];
    		$objPHPExcel->getActiveSheet()->setCellValue('B' . $row_no, $er);

    		$ep = $row['name_of_enterprise'];
    		$objPHPExcel->getActiveSheet()->setCellValue('C' . $row_no, $ep);

    		$objPHPExcel->getActiveSheet()->setCellValue('D' . $row_no, $row['email_id']);

    		$objPHPExcel->getActiveSheet()->setCellValue('E' . $row_no, $row['mobile_no']);

    		$stage = $this->Minnovation->getInnvationStage();
    		$status = $this->Minnovation->getInnvationStatus();


    		$objPHPExcel->getActiveSheet()->setCellValue('F' . $row_no, $stage[$row['stage']]);
    		$objPHPExcel->getActiveSheet()->setCellValue('G' . $row_no, $status[$row['status']]);

    		$geography = $row['state'];
    		$objPHPExcel->getActiveSheet()->setCellValue('H' . $row_no, $geography);
    		$city = isset($row['city']) && $row['city'] != '' ? $row['city'] : $row['city_name'];

    		$objPHPExcel->getActiveSheet()->setCellValue('I' . $row_no, $city);

    		$userName = $this->Minnovation->getUsername($row['created_by']);


    		$partnersList = implode(',', array_unique($get_partner_id));
    		if ($row['sector'] == 'MCH') {
    			$sector_name = 'Maternal & child health';
    		} else if ($row['sector'] > 0) {
    			$sector_name = $this->Minnovation->getNewSectorDetails($row['sector']);
    		} else if ($row['program'] > 0) {
    			$sector_name = $this->Minnovation->getSectorName($row['pitch_id']);
    		} else {
    			$sector_name = $row['sector'];
    		}

    		$sector_len = $sector_name;

    		$objPHPExcel->getActiveSheet()->setCellValue('K' . $row_no, $sector_len);
    		$objPHPExcel->getActiveSheet()->setCellValue('L' . $row_no, $row['Sub_Sector']);
    		$objPHPExcel->getActiveSheet()->setCellValue('M' . $row_no, $row['Stage_of_operation']);

    		$asArray = array();
    		$associate = $this->Mincharge->getAssociate(array('innovation' => $row['id'], 'active' => 'Active'));

    		foreach ($associate as $as):
    			$asArray[] = $as['emp_name'];
    		endforeach;
    		$row['associate_emp_name'] = implode(', ', $asArray);
    		$objPHPExcel->getActiveSheet()->setCellValue('N' . $row_no, $row['associate_emp_name']);

    		if ($row['program'] == '1') {
    			$program = 'EIR';
    			$submitted_date1 = ($row['eir_submitted_date'] != '0000-00-00') && $row['eir_submitted_date'] != '' ? date("d-M-y", strtotime($row['eir_submitted_date'])) : '-';
    			$submitted_date = $submitted_date1;
    		} else if ($row['program'] == '2') {
    			$program = 'SEED';
    			if ($row['id'] == '2336')
    				$submitted_date = '27-May-14';
    		} else if ($row['program'] == '3') {
    			$program = 'Unc Pitch';
    			$submitted_date1 = ($row['pitch_submitted_date'] != '0000-00-00') && $row['pitch_submitted_date'] != '' ? date("d-M-y", strtotime($row['pitch_submitted_date'])) : '-';
    			$submitted_date = $submitted_date1;
    		} else if ($row['program'] == '4') {
    			$program = 'Incubation';
    			$submitted_date1 = ($row['pitch_submitted_date'] != '0000-00-00') && $row['pitch_submitted_date'] != '' ? date("d-M-y", strtotime($row['pitch_submitted_date'])) : '-';
    			$submitted_date = $submitted_date1;
    		} else if ($row['program'] == '5') {
    			$program = 'FPAI IC';
    			$submitted_date1 = ($row['pitch_submitted_date'] != '0000-00-00') && $row['pitch_submitted_date'] != '' ? date("d-M-y", strtotime($row['pitch_submitted_date'])) : '-';
    			$submitted_date = $submitted_date1;
    		} else if ($row['program'] == '6') {
    			$program = 'UBS Challenge';
    			$submitted_date1 = ($row['pitch_submitted_date'] != '0000-00-00') && $row['pitch_submitted_date'] != '' ? date("d-M-y", strtotime($row['pitch_submitted_date'])) : '-';
    			$submitted_date = $submitted_date1;
    		} else if ($row['program'] == '0') {
    			$program = 'Incubation';
    			$submitted_date1 = ($row['submitted_date'] !== '0000-00-00') ? date("d-M-y", strtotime($row['submitted_date'])) : '-';
    			$submitted_date = $submitted_date1;
    		} else {
    			$program = 'Incubation';
    			$submitted_date1 = ($row['submitted_date'] !== '0000-00-00') && $row['submitted_date'] != '' ? date("d-M-y", strtotime($row['submitted_date'])) : '-';
    			$submitted_date = $submitted_date1;
    		}
    		$objPHPExcel->getActiveSheet()->setCellValue('J' . $row_no, $program);

    		$objPHPExcel->getActiveSheet()->setCellValue('O' . $row_no, $submitted_date);


    		$shortlist_comment = $this->Minnovation->getShortlistComments($row['copy_id'], '', 'created_by');
    		$repeated_users = array();
    		if (count($shortlist_comment) > 0) {
    			foreach ($shortlist_comment as $short_lists) {
    				if (!in_array($short_lists['created_by'], $repeated_users)) {

    					$users_name = $this->Minnovation->getUsername($short_lists['created_by']);

    					if ($short_lists['application_status'] == 12) {
    						$app_status = 'Open';
    					} else if ($short_lists['application_status'] == 3) {
    						$app_status = 'Closed';
    					} else if ($short_lists['application_status'] == 2) {
    						$app_status = 'On Hold';
    					} else if ($short_lists['application_status'] == 25) {
    						$app_status = 'Shortlisted';
    					} else if ($short_lists['application_status'] == 26) {
    						$app_status = 'Selected';
    					} else {
    						$app_status = '--';
    					}
    					$app_comment = $short_lists['comments'];
    					$app_date = date('d-M-Y', strtotime($short_lists['created_date']));
    					$app_username = $users_name[0]['emp_firstname'];
    					$objPHPExcel->getActiveSheet()->setCellValue('A' . $row_no, $inv_id);
    					$objPHPExcel->getActiveSheet()->setCellValue('B' . $row_no, $er);
    					$objPHPExcel->getActiveSheet()->setCellValue('C' . $row_no, $ep);
    					$objPHPExcel->getActiveSheet()->setCellValue('D' . $row_no, $row['email_id']);
    					$objPHPExcel->getActiveSheet()->setCellValue('E' . $row_no, $row['mobile_no']);
    					$objPHPExcel->getActiveSheet()->setCellValue('F' . $row_no, $stage[$row['stage']]);
    					$objPHPExcel->getActiveSheet()->setCellValue('G' . $row_no, $status[$row['status']]);
    					$objPHPExcel->getActiveSheet()->setCellValue('H' . $row_no, $geography);
    					$objPHPExcel->getActiveSheet()->setCellValue('I' . $row_no, $city);
    					$objPHPExcel->getActiveSheet()->setCellValue('K' . $row_no, $sector_len);
    					$objPHPExcel->getActiveSheet()->setCellValue('L' . $row_no, $row['Sub_Sector']);
    					$objPHPExcel->getActiveSheet()->setCellValue('M' . $row_no, $row['Stage_of_operation']);
    					$objPHPExcel->getActiveSheet()->setCellValue('J' . $row_no, $program);
    					$objPHPExcel->getActiveSheet()->setCellValue('O' . $row_no, $submitted_date);

    					$objPHPExcel->getActiveSheet()->setCellValue('P' . $row_no, $app_username);
    					$objPHPExcel->getActiveSheet()->setCellValue('Q' . $row_no, $app_comment);
    					$objPHPExcel->getActiveSheet()->setCellValue('R' . $row_no, $app_status);
    					$objPHPExcel->getActiveSheet()->setCellValue('S' . $row_no, $app_date);
    					$row_no++;
    					array_push($repeated_users, $short_lists['created_by']);
    				}
    			}
    		} else {
    			$app_status = 'Open';
    			$app_comment = '--';
    			$app_username = '--';
    			$objPHPExcel->getActiveSheet()->setCellValue('P' . $row_no, $app_username);
    			$objPHPExcel->getActiveSheet()->setCellValue('Q' . $row_no, $app_comment);
    			$objPHPExcel->getActiveSheet()->setCellValue('R' . $row_no, $app_status);
    			$objPHPExcel->getActiveSheet()->setCellValue('S' . $row_no, '--');
    			$row_no++;
    		}
    	}

    	$file_name = preg_replace('/[^A-Za-z0-9\_]/', '', 'Deals_user_status') . '.xlsx';
    	header('Content-Type: application/vnd.ms-excel');
    	header('Content-Disposition: attachment;filename="' . $file_name . '"');
    	header('Cache-Control: max-age=0');
    	header('Cache-Control: max-age=1');

    	header('Expires: Mon, 26 Jul 1997 05:00:00 GMT');
    	header('Last-Modified: ' . gmdate('D, d M Y H:i:s') . ' GMT');
    	header('Cache-Control: cache, must-revalidate');
    	header('Pragma: public');

    	$objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel2007');
    	ob_end_clean();

    	$objWriter->save('php://output');
    	exit;
    }

    /* deals by user status ends */

    function innovation_export_all($options = array()) {
    	$tab = $this->uri->segment(3);
    	$this->load->dbutil();
    	$this->load->model('Minnovation_reports');
    	$whereQuery = $this->Minnovation_reports->_searchReport($options);

    	if (isset($options['assigned_incharge']) && $options['assigned_incharge'] != "" && $whereQuery == "")
    		$whereQuery = "AA.associate_employee = '" . $options['assigned_incharge'] . "' and AA.status=1";
    	else if (isset($options['assigned_incharge']) && $options['assigned_incharge'] != "" && $whereQuery != '')
    		$whereQuery .= " and AA.associate_employee = '" . $options['assigned_incharge'] . "' and AA.status=1";

    	if (!empty($options['orderby']) && !empty($options['ordertype']))
    		$this->db->order_by($options['orderby'], $options['ordertype']);
    	else
    		$this->db->select("IP.program");
    	$this->db->join('assign_associate AA', 'AA.innovation =  IP.id', 'left');
    	$this->db->join('sector_category SC', 'SC.id =  IP.sector', 'left');
    	$this->db->join('source_master SM', 'IP.source = SM.id', 'left');
    	$this->db->join('instance_master IM', 'IP.instance = IM.id', 'left');
    	$this->db->join('inv_user INV', 'INV.inv_no = IP.innovation_id', 'left');
    	$this->db->join('pitch_user pitch', 'pitch.inno_id = IP.innovation_id', 'left');
    	$this->db->join('pitch_step1_info', 'pitch_step1_info.pitch_id = pitch.pitch_id', 'left');
    	$this->db->join('pitch_step2', 'pitch_step2.pitch_id=pitch.pitch_id', 'left');
    	$this->db->join('inv_additional_info iaf ', 'iaf.inv_user_id=INV.id', 'left');
    	$this->db->join('inv_ent_info iet ', 'iet.inv_user_id=INV.id', 'left');
    	$this->db->join('inv_impact imt ', 'imt.inv_user_id=INV.id', 'left');
    	$this->db->join('eir_user eir', 'eir.innovation_no = IP.innovation_id', 'left');
    	$this->db->join('inv_member inv_mem', 'inv_mem.inv_user_id = INV.id', 'left');

    	$this->db->join('(SELECT innovation_id, id, fstage, donor_fit, LIS
    		FROM grading_feedback AS ga
    		INNER JOIN (
    		SELECT max( id ) AS maxid
    		FROM grading_feedback
    		GROUP BY innovation_id
    	) AS gb ON ga.id = gb.maxid) as GF', 'GF.innovation_id=IP.id', 'left');
    	$this->db->join('shortlist_comments ISC', 'ISC.inv_id = IP.id', 'left');
    	$this->db->distinct();
    	$this->db->group_by('IP.program');
    	if (isset($options['innovation_score'])) {
    		$this->db->select('INS.*');
    		$this->db->join('innovation_score INS', 'INS.innovation = IP.id', 'left');
    	}

    	if (!empty($whereQuery))
    		$query = $this->db->get_where('innovation_pool IP', $whereQuery);
    	else
    		$query = $this->db->get('innovation_pool IP');
    	if ($query->num_rows() > 1) {
    		foreach ($query->result_array() as $row) {
    			$data[] = $row;
    		}

    		echo "invalid";
    	} else {

    	}
    }

    public function innovation_download($options = array()) { 

    	$tab = $this->uri->segment(3);
    	$this->load->dbutil();
    	$this->hris = $this->load->database('hris', TRUE);
    	$this->load->model('Minnovation_reports');

        if ($options['deals_tab'] == "mydeals") {  // for my deals
        	$this->load->model('Mincharge');
        	$innovation = $this->Mincharge->getAssociateInnovation($this->session->userdata('emp_number'));
        	$innovation = (count($innovation)) ? $innovation : array();
        	$options['associate'] = $innovation;
        	if ($options['stage'] == '')
                $options['sstage'] = '!5'; // incubation stage
            if ($options['status'] == '')
                $options['sstatus'] = '!8'; // incubation status
        }
        if ($tab == 'decision_pending') { // for decision pending
        	$options['status'] = '!3';
        	$options['grading_status'] = '1';
        	$options['decision_status'] = '6';
        }

        if ($this->session->userdata('role_id') == 4) {
        	if ($this->session->userdata('independent_shortlist') == 1) {
        		unset($options['sector']);
        		unset($options['program']);
        	}
        }

        $whereQuery = $this->Minnovation_reports->_searchReport($options);


        if (isset($options['assigned_incharge']) && $options['assigned_incharge'] != "" && $whereQuery == "")
        	$whereQuery = "AA.associate_employee = '" . $options['assigned_incharge'] . "' and AA.status=1";
        else if (isset($options['assigned_incharge']) && $options['assigned_incharge'] != "" && $whereQuery != '')
        	$whereQuery .= " and AA.associate_employee = '" . $options['assigned_incharge'] . "' and AA.status=1";

        if ($this->session->userdata('role_id') == 4) {
        	if ($this->session->userdata('independent_shortlist') == 1) {

        		$sector_arr = $this->session->userdata('sectorAccess');
        		$prgm_arr = $this->session->userdata('programAccess');
        		if ($whereQuery == '') {
        			$whereQuery = "SC.id IN (" . $sector_arr . ") and IP.program IN (" . $prgm_arr . ")";
        		} else if ($whereQuery != '') {
        			$whereQuery .= "and SC.id IN (" . $sector_arr . ") and IP.program IN (" . $prgm_arr . ")";
        		}
        	}
        }

        if (!empty($options['orderby']) && !empty($options['ordertype']))
        	$this->db->order_by($options['orderby'], $options['ordertype']);
        else
        	$this->db->order_by('submitted_date', 'desc');

        $this->db->select("CONCAT(IP.copy_id,'_',IP.partner_id,'_',IP.partner_count) as Innovation_id,IP.name_of_enterprise as Name_of_the_Enterprise,IP.name_of_entrepreneur as Name_of_Entrepreneur,IP.email_id as Email,IP.mobile_no as Mobile_No,(CASE WHEN (IP.source = '0' || IP.source = '101' || IP.source = '103' || IP.source = '123' || IP.source = '124' || IP.source = '125' || IP.source = '126' || IP.source = '127' || IP.source = '128' || IP.source = '129' || IP.source = '130') THEN 'Website' WHEN (IP.source = '2') THEN 'Imported' ELSE (select CONCAT_WS(' ',emp_first_name) from hr_user_profile where id = IP.created_by) END) as Source");
        $this->db->select("SM.source_name as Source_Name,IF(IP.partner_id = '02', IP.sector, SC.sector) as Sector, IF(IP.program=0 ,InvSubCat.sector, IF(IP.program=3 , PitSubCat.sector, IF(IP.program=5 , PitSubCat.sector, IF(IP.program=6, pitch_step2.sub_sector, IF(IP.program=14, INV.sub_sector, ''))))) as Sub_Sector, prog.program_name as Program");
        $this->db->select("IP.country as Country, ES.state_name as State,IF(IP.city != '', IP.city, eir_ct.city_name) as City, IP.stage as Stage,IP.status as Status");
        $this->db->select("(select partner_name from hr_partner_type where id = IP.partner_id) as Partner");
        $this->db->select("(select GROUP_CONCAT(CONCAT_WS(' ',emp.emp_first_name,emp.emp_last_name)) as employees from hr_user_profile emp
        	Join assign_associate AA1 ON emp.id = AA1.associate_employee where IP.id = AA1.innovation and AA1.status = 1 group by AA1.innovation ) as Assigned_Incharge", false);
        //         $pitch_language = isset($row['lang_code']) && $row['lang_code'] != '' ? $row['lang_code'] : 'en';
        // if ($pitch_language == 'hi') {
        //     $deals_lang = 'Hindi';
        // } else {
        //     $deals_lang = 'English';
        // }
        $this->db->select("IP.other_partner_id as Applied_to_Partners");
        $this->db->select("DATE_FORMAT(IP.created_date, '%d-%b-%y') as Registered_Date");
        $this->db->select('INV.id, pitch.pitch_id');
        $this->db->select("DATE_FORMAT(IFNULL(IFNULL(pitch.submitted_date, INV.submitted_date),eir.date_submitted), '%d-%b-%y') AS Submitted_Date ");
        $this->db->join('pitch_user pitch', 'IP.innovation_id=pitch.inno_id', 'left');
