        public function addportfolio($page = NULL) {  #echo"<pre>"; print_r($this->session->all_userdata());die;
			
			
			$getCompanyList  = $this->Mportfolio->get_all_data('port_company_data', array('company_status'=>1,'status'=>0),array('id','inv_id','name'));
			$data['getCompanyList'] = $getCompanyList;
        	$data['search_value'] = $search_value = (isset($_POST['search_value'])) ? $_POST['search_value'] : '';
        	$employee_id = $this->session->userdata['emp_number'];
        	$config['base_url'] = base_url() . "index.php/portfolio/addportfolio";
        	$config['total_rows'] = $this->Mportfolio->dealsCount($search_value, $employee_id);
        	$config['per_page'] = 1;
        	$config['uri_segment'] = '3';
        	$config['full_tag_open'] = '';
        	$config['full_tag_close'] = '';
        	if (isset($page) && is_numeric($page)) {
        		$offset = ($page - 1) * $config['per_page'];
        	} else {
        		$offset = 0;
        	}
        	$this->pagination->initialize($config);

        	$data['deals'] = $this->Mportfolio->getAllDeals($config['per_page'], $offset, $search_value, $employee_id);
        	foreach ($data['deals'] as $key => $value) {
            //getting source type
        		echo ' ** ' . $value['source'];
        		$userName = $this->Minnovation->getUsername($value['created_by']);
        		if ($value['source'] == '0' || $value['source'] == '123' || $value['source'] == '124' || $value['source'] == '125' || $value['source'] == '126' || $value['source'] == '127' || $value['source'] == '128' || $value['source'] == '129' || $value['source'] == '130') {
        			$data['deals'][$key]['source_type'] = 'Website';
        		} else if ($value['source'] == '2') {
        			$data['deals'][$key]['source_type'] = 'Imported';
        		} else {
        			$data['deals'][$key]['source_type'] = 'Added by' . " " . $userName[0]['emp_firstname'];
        		}

            //getting copy id
        		if ($value['copy_partner_id'] == '') {
        			$data['deals'][$key]['innovationId'] = $value['copy_id'] . "_" . $value['partner_id'] . "_" . $value['partner_count'];
        		} else {
        			$data['deals'][$key]['innovationId'] = $value['copy_id'] . "_" . $value['copy_partner_id'] . "_" . $value['partner_count'];
        		}

            //getting sector
        		$sector['id'] = $data['deals'][$key]['sector'];
        		$sector_details = $this->Mportfolio->getDetails('sector_category', $sector);
        		$data['deals'][$key]['sector_name'] = $sector_details[0]['sector'];

            //getting submitted date
        		if ($value['program'] == '3') {
        			$data['deals'][$key]['program_name'] = 'Unc Pitch';
        			$data['deals'][$key]['submitted_date'] = ($value['pitch_submitted_date'] != '0000-00-00') ? date("d-M-y", strtotime($value['pitch_submitted_date'])) : '-';
        		} else if ($value['program'] == '0') {
        			$data['deals'][$key]['program_name'] = 'Incubation';
        			$data['deals'][$key]['submitted_date'] = ($value['submitted_date'] !== '0000-00-00') ? date("d-M-y", strtotime($value['submitted_date'])) : '-';
        		} else if ($value['program'] == '4') {
        			$data['deals'][$key]['program_name'] = 'Incubation';
        			$data['deals'][$key]['submitted_date'] = ($value['pitch_submitted_date'] != '0000-00-00') ? date("d-M-y", strtotime($value['pitch_submitted_date'])) : '-';
        		} else if ($value['program'] == '6') {
        			$data['deals'][$key]['program_name'] = 'UBS Challenge';
        			$data['deals'][$key]['submitted_date'] = ($value['pitch_submitted_date'] != '0000-00-00') ? date("d-M-y", strtotime($value['pitch_submitted_date'])) : '-';
        		}

            //getting stage and status
        		$stage = $this->Minnovation->getInnvationStage();
        		$status = $this->Minnovation->getInnvationStatus();
        		$data['deals'][$key]['stage_text'] = $stage[$value['stage']];
        		$data['deals'][$key]['status_text'] = $status[$value['status']];

            //getting other partners
        		$other_partners = $value['other_partner_id'];
        		$partnersList = $get_partner_id = array();
        		if ($other_partners != '') {
        			$explode_partners = explode(',', $other_partners);
        			for ($i = 0; $i < count($explode_partners); $i++) {
        				$individual_id = $explode_partners[$i];
        				$this->db->select('t1.partner_id');
        				$this->db->where("t2.id", $individual_id);
        				$this->db->join('inv_user t2', 't2.inv_no = t1.innovation_id', 'left');
        				$query = $this->db->get('innovation_pool t1');
        				if ($query->num_rows() > 0) {
        					foreach ($query->result_array() as $partner_row) {
        						if ($partner_row['partner_id'] == '01') {
        							$partner_nam = 'Villgro India';
        							array_push($get_partner_id, $partner_nam);
        						} else if ($partner_row['partner_id'] == '02') {
        							$partnersList = 'Villgro Kenya';
        						} else if ($partner_row['partner_id'] == '03') {
        							$partnersList = 'Menterra';
        						} else if ($partner_row['partner_id'] == '04') {
        							$partner_nam = 'Startup Oasis';
        							array_push($get_partner_id, $partner_nam);
        						} else if ($partner_row['partner_id'] == '05') {
        							$partner_nam = 'IIMC';
        							array_push($get_partner_id, $partner_nam);
        						} else if ($partner_row['partner_id'] == '06') {
        							$partner_nam = 'KIIT';
        							array_push($get_partner_id, $partner_nam);
        						} else if ($partner_row['partner_id'] == '07') {
        							$partner_nam = 'SIIC';
        							array_push($get_partner_id, $partner_nam);
        						}
        					}
        				}
        			}
        		}
        		$data['deals'][$key]['partnersList'] = implode(',', array_unique($get_partner_id));


            //getting copied date
        		$copied_date1 = $value['copied_date'];
        		if ($copied_date1 != null) {
        			$data['deals'][$key]['copied_date'] = date("d-m-Y", strtotime($copied_date1));
        		} else {
        			$data['deals'][$key]['copied_date'] = '';
        		}

            //getting assign incharge
        		$asArray = array();
        		$associate = $this->Mincharge->getAssociate(array('innovation' => $value['id'], 'active' => 'Active'));

        		foreach ($associate as $as):
        			$asArray[] = $as['emp_name'];
        		endforeach;
        		$data['deals'][$key]['assign_incharge'] = implode(', ', $asArray);
        	}

        	$this->load->vars($data);
        	$this->load->view('portfolio/addportfolio');
        }
		
		public function update_merge_company() { 
		
			$company_id = $_POST['company_id'];
			$current_inv_id = $_POST['current_inv_id'];
			$data['company_id'] = $company_id;
			$data['current_inv_id'] = $current_inv_id;
			$data['status'] = 1;
			$this->Mportfolio->insertPortfolioDetail('port_company_merge', $data);
			
			$match['id'] = $current_inv_id;
			$data_ip['merge_status'] =1;
			$data_ip['stage'] = '12';
        	$data_ip['status'] = '12';
			$this->Mportfolio->updatePortfolioDetail('innovation_pool', $data_ip, $match);
			
			$response['innvId'] = '';
			$response['company_id'] = $company_id;
			$response['current_inv_id'] = $current_inv_id;
			$response['status'] = 1;
			
			$employees = $this->Sector_model->getEmpId($_POST['inv_id']);
        	$emp_Ids = array_map(function ($emp_Ids) {
        		return $emp_Ids['associate_employee'];
        	}, $employees);
        	$employees_id = rtrim(implode(',', $emp_Ids), ',');

        	$log_data = array(
        		'innovation_id' => $current_inv_id,
        		'stage' => '12',
        		'status' => '12',
        		'assigned_user' => $employees_id,
        		'modified_by' => $this->session->userdata['emp_number'],
        		'modified_date' => date('Y-m-d H:i:s')
        	);
        	$table_log = "application_status_log";
        	$result = $this->Minnovation->pitch_insert($table_log, $log_data);

			$getData['id'] = $company_id;
        	$get_company_data = $this->Mportfolio->getDetails('port_company_data', $getData);
			if(!empty($get_company_data)){
				$response['innvId'] = $get_company_data[0]['inv_id'];
			}
        	echo json_encode($response);

		}
		
