        public function DTaddportfolio() {  
		
			
        	$requestData = $_POST;

        	$columns = array(
        		0 => 'IP.id',
        		1 => 'copy_id',
        		2 => 'name_of_enterprise',
        		3 => 'name_of_entrepreneur',
        		4 => 'sector',
        		5 => 'stage',
        		6 => 'IP.status',
        		7 => 'source_type',
        		8 => 'mobile_no',
        		9 => 'program_name',
        		10 => 'email_id',
        		11 => 'assign_incharge',
        		12 => 'partnersList',
        		13 => 'copied_date',
        		14 => 'city',
        		15 => 'submitted_date',
        	);
        	$employee_id = $this->session->userdata['emp_number'];

        	$data['deals'] = $totalrows = $this->Mportfolio->DTdealsCount($_POST['search_value'], $employee_id, $columns, $requestData);
        	$query = $this->Mportfolio->getDTAllDeals($requestData['length'], $requestData['start'], $_POST['search_value'], $employee_id, $columns, $requestData);
        	$totalFiltered = $totalrows;
        	$totalData = count($query);
        	$data = array();
        	$i = $requestData['start'] + 1;
        	$start = $requestData['start'];
			
			

        	foreach ($query as $row) {

        		$nestedData = array();
//            $nestedData[] = '<div class="input-group"><input type="checkbox" class="check_box" aria-label="Checkbox for following text input"></div>';
            //getting copy id
        		if ($row['copy_partner_id'] == '') {
        			$nestedData[] = $row['copy_id'] . "_" . $row['partner_id'] . "_" . $row['partner_count'];
        		} else {
        			$nestedData[] = $row['copy_id'] . "_" . $row['copy_partner_id'] . "_" . $row['partner_count'];
        		}
        		$nestedData[] = $row['name_of_enterprise'];
        		$nestedData[] = $row['name_of_entrepreneur'];

            //getting sector
        		$sector['id'] = $row['sector'];
        		$sector_details = $this->Mportfolio->getDetails('sector_category', $sector);
        		$nestedData[] = $sector_details[0]['sector'];

            //getting stage and status
        		$stage = $this->Minnovation->getInnvationStage();
        		$status = $this->Minnovation->getInnvationStatus();
        		$nestedData[] = $stage[$row['stage']];
        		$nestedData[] = $status[$row['status']];


            //getting source type
        		$userName = $this->Minnovation->getUsername($row['created_by']);
        		if ($row['source'] == '0' || $row['source'] == '123' || $row['source'] == '124' || $row['source'] == '125' || $row['source'] == '126' || $row['source'] == '127' || $row['source'] == '128' || $row['source'] == '129' || $row['source'] == '130') {
        			$nestedData[] = 'Website';
        		} else if ($row['source'] == '2') {
        			$nestedData[] = 'Imported';
        		} else {
        			$nestedData[] = 'Added by' . " " . $userName[0]['emp_firstname'];
        		}

        		$nestedData[] = $row['mobile_no'];
            //getting submitted date
        		if ($row['program'] == '3') {
        			$nestedData[] = 'Unc Pitch';
        		} else if ($row['program'] == '0' || $row['program'] == '4') {
        			$nestedData[] = 'Incubation';
        		} else if ($row['program'] == '1') {
        			$nestedData[] = 'EIR';
        		} else if ($row['program'] == '2') {
        			$nestedData[] = 'SEED';
        		} else if ($row['program'] == '6') {
        			$nestedData[] = 'UBS Challenge';
        		}else{
					$nestedData[] = "";
				}
				
        		$nestedData[] = $row['email_id'];

            //getting assign incharge
        		$asArray = array();
        		$associate = $this->Mincharge->getAssociate(array('innovation' => $row['id'], 'active' => 'Active'));

        		foreach ($associate as $as):
        			$asArray[] = $as['emp_name'];
        		endforeach;
        		$nestedData[] = implode(', ', $asArray);


            //getting other partners
        		$other_partners = $row['other_partner_id'];
        		$partnersList = $get_partner_id = array();
        		if ($other_partners != '') {
        			$explode_partners = explode(',', $other_partners);
        			for ($i = 0; $i < count($explode_partners); $i++) {
        				$individual_id = $explode_partners[$i];
        				$this->db->select('t1.partner_id');
        				$this->db->where("t2.id", $individual_id);
        				$this->db->join('inv_user t2', 't2.inv_no = t1.innovation_id', 'left');
        				$query = $this->db->get('innovation_pool t1');
        				if ($query->num_rows() > 0) {
        					foreach ($query->result_array() as $partner_row) {
        						if ($partner_row['partner_id'] == '01') {
        							$partner_nam = 'Villgro India';
        							array_push($get_partner_id, $partner_nam);
        						} else if ($partner_row['partner_id'] == '02') {
        							$partnersList = 'Villgro Kenya';
        						} else if ($partner_row['partner_id'] == '03') {
        							$partnersList = 'Menterra';
        						} else if ($partner_row['partner_id'] == '04') {
        							$partner_nam = 'Startup Oasis';
        							array_push($get_partner_id, $partner_nam);
        						} else if ($partner_row['partner_id'] == '05') {
        							$partner_nam = 'IIMC';
        							array_push($get_partner_id, $partner_nam);
        						} else if ($partner_row['partner_id'] == '06') {
        							$partner_nam = 'KIIT';
        							array_push($get_partner_id, $partner_nam);
        						} else if ($partner_row['partner_id'] == '07') {
        							$partner_nam = 'SIIC';
        							array_push($get_partner_id, $partner_nam);
        						}
        					}
        				}
        			}
        		}
        		$nestedData[] = implode(',', array_unique($get_partner_id));

				

            //getting copied date
        		$copied_date1 = $row['copied_date'];
        		if ($copied_date1 != null) {
        			$nestedData[] = date("d-m-Y", strtotime($copied_date1));
        		} else {
        			$nestedData[] = '';
        		}
        		$nestedData[] = $row['city'];

            //getting submitted date
        		if ($row['program'] == '3' || $row['program'] == '4' || $row['program'] == '6') {
        			$nestedData[] = ($row['pitch_submitted_date'] != '0000-00-00') ? date("d-M-y", strtotime($row['pitch_submitted_date'])) : '-';
        		} else if ($row['program'] == '0') {
        			$nestedData[] = ($row['submitted_date'] !== '0000-00-00') ? date("d-M-y", strtotime($row['submitted_date'])) : '-';
        		} else if ($row['program'] == '1') {
        			$nestedData[] = ($row['eir_date'] !== '0000-00-00') ? date("d-M-y", strtotime($row['eir_date'])) : '-';
        		} else if ($row['program'] == '2') {
        			$nestedData[] = ($row['seed_date'] !== '0000-00-00 00:00:00') ? date("d-M-y", strtotime($row['seed_date'])) : '-';
        		}else{
					$nestedData[] = "";
				}
				
				
				
//            $nestedData[] = '<a href="' . base_url() . 'index.php/portfolio/company_data/' . $row['id'] . '" class="add-portbtn">Add</a>';
        		$nestedData[] = '<a href="javascript:void(0)" id="portbtn_' . $row['id'] . '" onclick="addInnvPool(' . $row['id'] . ')" class="add-portbtn">Add</a>';
				
				
				

        		$data[] = $nestedData;
				
				
				
        		$i++;
				
        	}
        	$json_data = array(
        		"draw" => intval($requestData['draw']),
        		"recordsTotal" => intval($totalData),
        		"recordsFiltered" => intval($totalFiltered),
        		"data" => $data
        	);
        	echo json_encode($json_data);
        }

