        function getOrdinal($number) {
        	$digit = abs($number) % 10;
        	$ext = 'th';
        	$ext = ((abs($number) % 100 < 21 && abs($number) % 100 > 4) ? 'th' : (($digit < 4) ? ($digit < 3) ? ($digit < 2) ? ($digit < 1) ? 'th' : 'st' : 'nd' : 'rd' : 'th'));
        	return $number . $ext;
        }

        public function company_data($id = '') {
        	if ($id != '')
        		check_partner_privilege($id);
        	$option['id'] = $c_option['inv_id'] = $invest_option['inv_id'] = $data['innovation_id'] = $id;
        	$msaoption['innovation_id'] = 'INV' . $id;
        	$status = 3;
        	$invest_option['status'] = 1;

        	$data['company_data'] = $this->Mportfolio->getDetails('port_company_data', $c_option);
        	$data['business_nature'] = $this->Mportfolio->getDetails('port_business', $c_option);
        	$data['managementDetails'] = $this->Mportfolio->getDetails('port_management', $c_option, $status);
        	$data['governanceDetails'] = $this->Mportfolio->getDetails('port_governance', $c_option, $status);
        	$data['relationDetails'] = $this->Mportfolio->getDetails('port_villgro_relation', $c_option);
        	$data['villgro_incubation'] = $this->Mportfolio->getDetails('port_incubation_relation', $c_option);
        	$data['capTableDetails'] = $this->Mportfolio->getDetails('port_cap_table', $c_option, $status);
        	$data['otherInterests'] = $this->Mportfolio->getDetails('port_other_interest', $c_option, $status);
        	$data['get_innovation'] = $this->Mportfolio->getDetails('innovation_pool', $option);
        	$data['get_master_company'] = $this->Mportfolio->getDetails('company_master_data', $msaoption);

        	if ($data['company_data'][0]['company_status'] == 3) {
        		$data['invest_list'] = $this->Mportfolio->getDetails('port_company_data_exit_invest', $invest_option);
        	}

        	$assign['created_by'] = $this->session->userdata('emp_number');

        	$welcome = $this->Mportfolio->getDetails('port_onboarding_welcome', $assign, 1);
        	$welcome_count = isset($welcome) && count($welcome) > 0 ? count($welcome) : 1;
        	$data['welcome_count'] = $this->getOrdinal($welcome_count);


        	$sector['id'] = isset($data['business_nature']) ? $data['business_nature'][0]['sector'] : $data['get_innovation'][0]['sector'];
        	$sector_details = $this->Mportfolio->getDetails('sector_category', $sector);
        	#Sector Name Dashboard
			$data['sector_name'] = $sector_details[0]['sector'];
			$business_nature_year = $this->Mportfolio->getDetails('port_business_year', $c_option);
			if($business_nature_year[0]['sector']!=''){
				$get_inc_sector_year =array();
				$sectorData =array();
				if($business_nature_year[0]['sector']!=''){
					$get_inc_sector_year = explode(',',$business_nature_year[0]['sector']);
					if(!empty($get_inc_sector_year)){
						foreach($get_inc_sector_year as $sectorId){
							$sectorLists = $this->Mportfolio->getSectorIn($sectorId);
							$sectorData[] = $sectorLists[0]['sector'];
						}
					}
					if(!empty($sectorData)){
						$data['sector_name'] = implode(',',$sectorData);
					}
				}
			}
			#Sector Name Dashboard

        	$data['isAssociate'] = $this->Mincharge->isAssociateUser($id, $this->session->userdata('emp_number'));
        	$data['find_lead'] = $this->findSectorLead($sector['id']);

        	$this->load->vars($data);
        	$this->load->view('portfolio/onboarding/company_data');
        }

        public function addCompany() {
        	$data = array();
        	$option['inv_id'] = $mainoption['id'] = $data['inv_id'] = $invest_option['inv_id'] = $_POST['innovation_id'];
        	$data['name'] = $_POST['company_name'];
        	$data['cin'] = $_POST['cin_number'];
        	$data['reg_address'] = $_POST['reg_address'];
        	$data['reg_city'] = $_POST['reg_city'];
        	$data['reg_pincode'] = $_POST['reg_pin'];
        	$data['other_address'] = $_POST['other_address'];
        	$data['other_city'] = $_POST['other_city'];
        	$data['other_pincode'] = $_POST['other_pin'];
        	$data['innovation_id'] = $_POST['company_inv'];
        	$data['company_status'] = $_POST['company_status'];
        	$data['partner_id'] = $this->session->userdata('partner_id');
        	$data['document'] = $this->portfolio_file_upload('app', 'uploads/portfolio/company', 'document_file', 'doc|docx|ppt|pptx|pdf', $_POST['old_doc']);

        	if ($_POST['company_status'] == 3) {
        		$data['company_valuation'] = $_POST['company_valuation'];
        		$data['villgro_investment'] = $_POST['villgro_invest'];
//            $data['investor_name'] = $_POST['investor_name'];
//            $data['size_of_round'] = $_POST['size_round'];
        		for ($i = 0; $i < count($_POST['investor_name']); $i++) {
        			if ($_POST['investor_name'][$i] != '' && $_POST['size_round'][$i] != '') {
        				$invest_option['id'] = $_POST['invest_id'][$i];
        				$invest_data['inv_id'] = $_POST['innovation_id'];
        				$invest_data['investor_name'] = $_POST['investor_name'][$i];
        				$invest_data['round_size'] = $_POST['size_round'][$i];
        				$invest_data['status'] = 1;

        				$invest_checkExist = $this->Mportfolio->getDetails('port_company_data_exit_invest', $invest_option);
        				if (count($invest_checkExist) > 0) {
        					$invest_data['updated_by'] = $this->session->userdata('emp_number');
        					$query = $this->Mportfolio->updatePortfolioDetail('port_company_data_exit_invest', $invest_data, $invest_option);
        				} else {
        					$invest_data['created_by'] = $this->session->userdata('emp_number');
        					$invest_data['created_at'] = date("Y-m-d H:i:s");
        					$query = $this->Mportfolio->insertPortfolioDetail('port_company_data_exit_invest', $invest_data);
        				}
        			}
        		}
        	} else {
