        		$query = $this->Mportfolio->insertPortfolioDetail('port_villgro_relation', $r_data);
        		$relation_id = $this->db->insert_id();
        	}

        	for ($i = 0; $i < count($_POST['mentor_name']); $i++) {
        		if ($_POST['mentor_name'][$i] != '') {
        			$data = array();

        			$option['inv_id'] = $data['inv_id'] = $_POST['innovation_id'];
        			$option['id'] = $_POST['mentor_id'][$i];

        			$data['relation_id'] = $relation_id;
        			$data['name'] = $_POST['mentor_name'][$i];
        			$data['start_date'] = (isset($_POST['start_date'][$i]) && $_POST['start_date'][$i] != '') ? date('Y-m-d', strtotime($_POST['start_date'][$i])) : '';
        			$data['end_date'] = (isset($_POST['end_date'][$i]) && $_POST['end_date'][$i] != '') ? date('Y-m-d', strtotime($_POST['end_date'][$i])) : '';
//                $data['sow_number'] = $_POST['sow_number'][$i];
        			$data['area'] = $_POST['area_name'][$i];

        			$upload_path = $_SERVER['DOCUMENT_ROOT'] . '/' . base_upload_path() . 'uploads/portfolio/mentor';

        			if ($_FILES["sow_doc"]["name"][$i] != "") {
        				$split_name = explode('.', $_FILES["sow_doc"]["name"][$i]);
        				$get_extension = array_pop($split_name);
        				$get_name = implode('', $split_name);
        				$this->load->library('upload');
        				$config['upload_path'] = $upload_path;
        				$config['allowed_types'] = 'doc|docx|ppt|pptx|pdf';
        				$rename_file = str_replace(' ', '_', strtolower($get_name));
        				$new_name = preg_replace('/[^A-Za-z0-9\_]/', '', $rename_file);
        				$config['file_name'] = date('Ymdhis') . '_' . $new_name . '.' . $get_extension;

        				$this->upload->initialize($config);

        				$_FILES['upload_single']['name'] = $_FILES['sow_doc']['name'][$i];
        				$_FILES['upload_single']['tmp_name'] = $_FILES['sow_doc']['tmp_name'][$i];
        				$_FILES['upload_single']['size'] = $_FILES['sow_doc']['size'][$i];
        				$_FILES['upload_single']['type'] = $_FILES['sow_doc']['type'][$i];
        				$_FILES['upload_single']['error'] = $_FILES['sow_doc']['error'][$i];

        				if (!$this->upload->do_upload('upload_single')) {
        					$upload_error = $this->upload->display_errors();
        					echo $upload_error . "--" . $i;
        				} else {
        					$upload_data = $this->upload->data();
        					$data['sow_document'] = $upload_data['file_name'];
        				}
        				unset($config);
        			} else if (isset($_POST['old_sow_doc'][$i]) && $_POST['old_sow_doc'][$i] != '') {
        				$data['sow_document'] = $_POST['old_sow_doc'][$i];
        			} else {
        				$data['sow_document'] = '';
        			}

        			$checkExist = $this->Mportfolio->getDetails('port_villgro_relation_mentor', $option);
        			if (count($checkExist) > 0) {
        				$data['updated_by'] = $this->session->userdata('emp_number');
        				$data['status'] = 0;
        				$query = $this->Mportfolio->updatePortfolioDetail('port_villgro_relation_mentor', $data, $option);
        			} else {
        				$data['created_by'] = $this->session->userdata('emp_number');
        				$data['created_at'] = date("Y-m-d H:i:s");
        				$query = $this->Mportfolio->insertPortfolioDetail('port_villgro_relation_mentor', $data);
        			}
        		}
        	}
        	if ($query) {
        		$this->session->set_flashdata('successMsg', "Villgro relationship details saved successfully");
        	} else {
