					$get_inc_sector_year = explode(',',$business_nature_year[0]['sector']);
					if(!empty($get_inc_sector_year)){
						foreach($get_inc_sector_year as $sectorId){
							$sectorLists = $this->Mportfolio->getSectorIn($sectorId);
							$sectorData[] = $sectorLists[0]['sector'];
						}
					}
					if(!empty($sectorData)){
						$data['sector_name'] = implode(',',$sectorData);
					}
				}
			}
			#Sector Name Dashboard

        	$data['isAssociate'] = $this->Mincharge->isAssociateUser($id, $this->session->userdata('emp_number'));
        	$data['find_lead'] = $this->findSectorLead($sector['id']);

        	$this->load->vars($data);
        	$this->load->view('portfolio/onboarding/interested_parties');
        }

        public function addInterestedParties() {
        	for ($i = 0; $i < count($_POST['name']); $i++) {
        		if ($_POST['name'][$i] != '') {
        			$data = array();
        			$option['inv_id'] = $data['inv_id'] = $_POST['innovation_id'];
        			$option['id'] = $_POST['id'][$i];

        			$data['relation'] = $_POST['relation'][$i];
        			$data['comments'] = $_POST['comments'][$i];
        			$data['name'] = $_POST['name'][$i];

        			$table = "port_other_interest";
        			$checkExist = $this->Mportfolio->getDetails($table, $option);
        			if (count($checkExist) > 0) {
        				$data['updated_by'] = $this->session->userdata('emp_number');
        				$data['status'] = 0;
        				$query = $this->Mportfolio->updatePortfolioDetail($table, $data, $option);
        			} else {
        				$data['created_by'] = $this->session->userdata('emp_number');
        				$data['created_at'] = date("Y-m-d H:i:s");
        				$query = $this->Mportfolio->insertPortfolioDetail($table, $data);
        			}
        		}
        	}
        	if ($query) {
        		$this->session->set_flashdata('successMsg', "Interested parties details saved successfully");
        		$this->session->set_userdata('interest', '1');
        	} else {
        		$this->session->set_flashdata('errormsg', 'Value Missing');
        		$this->session->set_userdata('interest', '0');
        	}
        	$this->session->set_userdata('interest', '1');
        	redirect('portfolio/interested_parties/' . $_POST['innovation_id']);
        }

        public function deletePortfolioConfig() {
        // $this->db->set('status', 3);
        	$fields['status'] = $planField['status'] = 3;
        	$getField = $this->input->post('fields');
        	if ($getField != '') {
        		$exfields = explode(',', $getField);
        		foreach ($exfields as $ef) {
        			$fields[$ef] = '';
        		}
        	}
        	$id = $this->input->post('id');
        	$table = $this->input->post('table');
        	$temp_table = $this->input->post('temp_table');

        	$column = $this->input->post('column');
        	$cond[$column] = $id;

        	$m_query = $this->Mportfolio->deleteConfigDetails($table, $id, $fields);
        	$t_query = $this->Mportfolio->deleteTempConfigDetails($temp_table, $cond, $fields);

        	$plan_table = $this->input->post('plan_table');
        	if ($plan_table != '') {
        		$plan_column = $this->input->post('plan_column');
        		$plan[$plan_column] = $id;
        		$this->Mportfolio->deleteTempConfigDetails($plan_table, $plan, $planField);
        	}

        	if ($m_query) {
        		echo '1';
        	} else {
        		echo '0';
        	}
        }

        public function deleteImpact() {
        	$data['status'] = 3;

        	$cond['financial_year'] = $plan_cond['financial_year'] = $vif_cond['financial_year'] = $this->input->post('finan_yr');
        	$cond['inv_id'] = $plan_cond['inv_id'] = $vif_cond['inv_id'] = $this->input->post('inv_id');
        	$cond['id'] = $plan_cond['plan_id'] = $vif_cond['port_vif_id'] = $this->input->post('del_id');

        	$table = $this->input->post('table');
        	$temp_table = $this->input->post('temp_table');

        	$m_query = $this->Mportfolio->deleteImpactdetails($table, $data, $cond);
        	$t_query = $this->Mportfolio->deleteImpactdetails($temp_table, $data, $cond);

        	if ($table == 'port_impact_metric') {
        		$del_achievement = $this->Mportfolio->deleteImpactdetails('plan_impact_metric', $data, $plan_cond);
        	}

        	if ($table == 'port_vif_funding') {
