        	}
        }

        public function deleteSeedFunding() {
        	$data['status'] = 3;
        	$id = $this->input->post('del_id');
        	$condition = "'" . implode("', '", $id) . "'";

        	$cond['financial_year'] = $vif_cond['financial_year'] = $this->input->post('finan_yr');
        	$cond['inv_id'] = $vif_cond['inv_id'] = $this->input->post('inv_id');
        	$target_vif = "id IN ($condition)";
        	$actual_vif = "port_vif_id IN ($condition)";

        	$table = $this->input->post('table');
        	$temp_table = $this->input->post('temp_table');

        	$m_query = $this->Mportfolio->deleteImpactdetails($table, $data, $cond, $target_vif);
        	$t_query = $this->Mportfolio->deleteImpactdetails($temp_table, $data, $cond, $target_vif);

        	if ($table == 'port_vif_funding') {
        		$del_achievement = $this->Mportfolio->deleteImpactdetails('plan_vif_funding', $data, $vif_cond, $actual_vif);
        	}

        	$option['inv_id'] = $this->input->post('inv_id');
        	$option['financial_year'] = $this->input->post('finan_yr');
        	$column_name = 'vif_approval';
        	$set_app[$column_name] = '0';

        	$check_value = $this->Mportfolio->getDetails($table, $option, '3');
        	if (count($check_value) == 0) {
        		$update_approval = $this->Mportfolio->approvalCompany('port_config_approval', $option, $set_app);
        		if ($update_approval) {
        			$config_approval = $this->Mportfolio->configApprovalUpdate('port_config_approval', $option);
        		}
        	}

        	if ($m_query) {
        		echo '1';
        	} else {
        		echo '0';
        	}
        }

        public function findSectorLead($sector) {
        	$option['employee_id'] = $this->session->userdata['emp_number'];
        	$option['partner_id'] = $this->session->userdata('partner_id');
        	$get_lead = $this->Mportfolio->getDetails('assign_sector_lead', $option);

        	$findSector = array();
        	foreach ($get_lead as $lead) {
        		array_push($findSector, $lead['sector_id']);
        	}

        	if (in_array($sector, $findSector)) {
        		$find = $this->session->set_userdata('sector_lead', '1');
        	} else {
        		$find = $this->session->set_userdata('sector_lead', '0');
        	}
        	return $find;
        }

