        	}

        	/* sales approve */
        	if ($get_awaitConfigApp[0]['sales_approval'] == 1 || $get_awaitConfigApp[0]['sales_approval'] == 2) {
        		$sales_tempDetails = $this->Mportfolio->getDetails('temp_sales_data', $option, $status);
