        		$m_query = $this->Mportfolio->insertPortfolioDetail('port_sales_data', $data);
        		$data['sales_id'] = $this->db->insert_id();
        		$t_query = $this->Mportfolio->insertPortfolioDetail('temp_sales_data', $data);
        	}
        	if ($t_query) {
        		$checkExist1 = $this->Mportfolio->getDetails('port_config_approval', $app_option);
