        	if ($year == '') {
        		if ($this->session->userdata['sector_lead'] == 1) {
        			$get_data = $this->Mportfolio->getConfigApprovalDetails('port_config_approval', $config_option, 'revenue_approval');
        			if (count($get_data) > 0) {
        				redirect('portfolio/revenue/' . $id . '/' . $get_data[0]['financial_year']);
