        	$qual_data['q_one_desc'] = $_POST['qOneDesc'];
        	$qual_data['apr_desc'] = $_POST['aprContent'];
        	$qual_data['may_desc'] = $_POST['mayContent'];
        	$qual_data['jun_desc'] = $_POST['junContent'];
        	$qual_data['q_two_desc'] = $_POST['qTwoDesc'];
        	$qual_data['jul_desc'] = $_POST['julContent'];
        	$qual_data['aug_desc'] = $_POST['augContent'];
        	$qual_data['sep_desc'] = $_POST['sepContent'];
        	$qual_data['q_three_desc'] = $_POST['qThreeDesc'];
        	$qual_data['oct_desc'] = $_POST['octContent'];
        	$qual_data['nov_desc'] = $_POST['novContent'];
        	$qual_data['dec_desc'] = $_POST['decContent'];
        	$qual_data['q_four_desc'] = $_POST['qFourDesc'];
        	$qual_data['jan_desc'] = $_POST['janContent'];
        	$qual_data['feb_desc'] = $_POST['febContent'];
        	$qual_data['mar_desc'] = $_POST['marContent'];

        	$qual_data['updated_by'] = $this->session->userdata('emp_number');
        	if ($this->session->userdata['sector_lead'] == 11) {
        		$qual_data['status'] = 1;
        		$qual_approval['vif_approval'] = 3;
        	} else {
        		$qual_data['status'] = 0;
        		$qual_approval['vif_approval'] = 1;
        		$qual_approval['config_approval'] = 1;
        	}

        	$check_qualit_exist = $this->Mportfolio->getDetails('port_qualitative_data', $qual_cond);
        	if (count($check_qualit_exist) > 0) {
        		$qual_option['id'] = $qual_temp_option['qualitative_id'] = $check_qualit_exist[0]['id'];
        		if ($this->session->userdata['sector_lead'] != 11 && $check_qualit_exist[0]['status'] == 1) {
        			$qual_edited['edited_status'] = 1;
        			$qm_query = $this->Mportfolio->updatePortfolioDetail('port_qualitative_data', $qual_edited, $qual_option);
        			$qt_query = $this->Mportfolio->updatePortfolioDetail('temp_qualitative_data', $qual_data, $qual_temp_option);
        		} else {
        			if ($this->session->userdata['sector_lead'] == 11)
        				$qual_data['edited_status'] = 0;
        			$qt_query = $this->Mportfolio->updatePortfolioDetail('temp_qualitative_data', $qual_data, $qual_temp_option);
        			$qm_query = $this->Mportfolio->updatePortfolioDetail('port_qualitative_data', $qual_data, $qual_option);
        		}
        	} else {
        		$qual_data['created_by'] = $this->session->userdata('emp_number');
        		$qual_data['created_at'] = date("Y-m-d H:i:s");
        		$qm_query = $this->Mportfolio->insertPortfolioDetail('port_qualitative_data', $qual_data);
        		$qual_data['qualitative_id'] = $this->db->insert_id();
        		$qt_query = $this->Mportfolio->insertPortfolioDetail('temp_qualitative_data', $qual_data);
        	}

        	if ($qt_query) {
        		$qual_checkExist1 = $this->Mportfolio->getDetails('port_config_approval', $app_option);
        		if (count($qual_checkExist1) > 0) {
        			$qual_query1 = $this->Mportfolio->updatePortfolioDetail('port_config_approval', $qual_approval, $app_option);
        		} else {
        			$qual_query1 = $this->Mportfolio->insertPortfolioDetail('port_config_approval', $qual_approval);
        		}
        		$this->session->set_flashdata('successMsg', "Seed funding details saved successfully");
        	} else {
        		$this->session->set_flashdata('errormsg', 'Value Missing');
        	}

        	for ($i = 0; $i < count($_POST['donor']); $i++) {
        		if ($_POST['donor'][$i] != '') {
        			$data = array();
        			$option['id'] = $temp['vif_id'] = $_POST["vif_id"][$i];
        			$option['inv_id'] = $app_option['inv_id'] = $approval['inv_id'] = $roption['inv_id'] = $data['inv_id'] = $_POST['innovation_id'];
        			$data['financial_year'] = $app_option['financial_year'] = $approval['financial_year'] = $roption['financial_year'] = $_POST['cur_finance'];
        			$data['donor'] = $_POST["donor"][$i];
        			$data['program'] = $_POST["program"][$i];
        			$data['grant_id'] = $_POST["grant"][$i];
        			$data['milestone'] = $_POST["milestone"][$i];
        			$data['amount'] = $_POST["amount"][$i];

        			$actualMonth = $this->actual_month();
//                $get_dis = explode(',', $_POST['month'][$i]);
//                $dis_search = array_search($get_dis[0], $actualMonth);
        			if ($_POST['month'][$i] < 4) {
        				$next_fy = $_POST['cur_finance'] + 1;
        			} else {
        				$next_fy = $_POST['cur_finance'];
        			}
        			$dis_date = '01-' . $_POST['month'][$i] . '-' . $next_fy;
        			$data['month'] = (isset($_POST['month'][$i]) && $_POST['month'][$i] != '') ? date('Y-m-01', strtotime($dis_date)) : '';

        			$rmvid = explode(',', $_POST['vif_rmv_id']);

        			for ($s = 0; $s < count($rmvid); $s++) {
        				$roption['id'] = $rmvid[$s];
        				$plan_option['port_vif_id'] = $rmvid[$s];
        				$status['status'] = 3;
        				$update_vif = $this->Mportfolio->updatePortfolioDetail('port_vif_funding', $status, $roption);
        				$update_plan_vif = $this->Mportfolio->updatePortfolioDetail('plan_vif_funding', $status, $plan_option);
        				$update_temp_vif = $this->Mportfolio->updatePortfolioDetail('temp_vif_funding', $status, $roption);
        			}

        			if ($this->session->userdata['sector_lead'] == 11) {
        				$data['status'] = 1;
        				$approval['vif_approval'] = 3;
        			} else {
        				$data['status'] = 0;
        				$approval['vif_approval'] = 1;
        				$approval['config_approval'] = 1;
        			}

        			$checkExist = $this->Mportfolio->getDetails('port_vif_funding', $option);
        			if (count($checkExist) > 0 && $checkExist[0]['status'] == 0) {
        				$data['updated_by'] = $this->session->userdata('emp_number');
        				$m_query = $this->Mportfolio->updatePortfolioDetail('port_vif_funding', $data, $option);
        				$t_query = $this->Mportfolio->updatePortfolioDetail('temp_vif_funding', $data, $temp);
        			} else if (count($checkExist) > 0 && $checkExist[0]['status'] == 1) {
        				$data['updated_by'] = $this->session->userdata('emp_number');
        				if ($this->session->userdata['sector_lead'] == 11) {
        					$main_data = $data;
        					$main_data['edited_status'] = 0;
        					$m_query = $this->Mportfolio->updatePortfolioDetail('port_vif_funding', $main_data, $option);
        				} else {
        					$edited['edited_status'] = 1;
        					$m_query = $this->Mportfolio->updatePortfolioDetail('port_vif_funding', $edited, $option);
        				}
        				$t_query = $this->Mportfolio->updatePortfolioDetail('temp_vif_funding', $data, $temp);
        			} else {
        				$data['created_by'] = $this->session->userdata('emp_number');
        				$data['created_at'] = date("Y-m-d H:i:s");
        				$m_query = $this->Mportfolio->insertPortfolioDetail('port_vif_funding', $data);
        				$data['vif_id'] = $this->db->insert_id();
        				$t_query = $this->Mportfolio->insertPortfolioDetail('temp_vif_funding', $data);
        			}
        		}
        	}

        	if ($t_query) {
        		$checkExist1 = $this->Mportfolio->getDetails('port_config_approval', $app_option);
        		if (count($checkExist1) > 0) {
        			$query1 = $this->Mportfolio->updatePortfolioDetail('port_config_approval', $approval, $app_option);
        		} else {
        			$query1 = $this->Mportfolio->insertPortfolioDetail('port_config_approval', $approval);
        		}
        		$this->session->set_flashdata('successMsg', "Seed funding details saved successfully");
        	} else {
        		$this->session->set_flashdata('errormsg', 'Value Missing');
        	}

