        public function fundraise($id = '', $year = '') {
        	if ($id != '')
        		check_partner_privilege($id);
        	$option['id'] = $appoption['inv_id'] = $c_option['inv_id'] = $config_option['inv_id'] = $data['innovation_id'] = $qual_option['inv_id'] = $id;
        	$data['company_data'] = $this->Mportfolio->getDetails('port_company_data', $c_option);
        	$data['business_nature'] = $this->Mportfolio->getDetails('port_business', $c_option);
        	$data['get_innovation'] = $this->Mportfolio->getDetails('innovation_pool', $option);

        	$sector['id'] = isset($data['business_nature']) ? $data['business_nature'][0]['sector'] : $data['get_innovation'][0]['sector'];
        	$sector_details = $this->Mportfolio->getDetails('sector_category', $sector);
        	#Sector Name Dashboard
			$data['sector_name'] = $sector_details[0]['sector'];
			$business_nature_year = $this->Mportfolio->getDetails('port_business_year', $c_option);
			if($business_nature_year[0]['sector']!=''){
				$get_inc_sector_year =array();
				$sectorData =array();
				if($business_nature_year[0]['sector']!=''){
					$get_inc_sector_year = explode(',',$business_nature_year[0]['sector']);
					if(!empty($get_inc_sector_year)){
						foreach($get_inc_sector_year as $sectorId){
							$sectorLists = $this->Mportfolio->getSectorIn($sectorId);
							$sectorData[] = $sectorLists[0]['sector'];
						}
					}
					if(!empty($sectorData)){
						$data['sector_name'] = implode(',',$sectorData);
					}
				}
			}
			#Sector Name Dashboard

        	$partner_id = $this->session->userdata('partner_id');
        	$data['fin_year'] = $this->Mportfolio->getAllFinancialYear($partner_id);
        	if ($year == '') {
        		foreach ($data['fin_year'] as $fy) {
        			if ($fy['status'] == 1) {
        				$f_year = $fy['fin_year'];
        			}
        		}
        	} else {
        		$f_year = $year;
        	}

        	$appoption['financial_year'] = $f_year;
        	$data['dataConfig'] = $this->configCount($id, $f_year);
        	$data['current_financial'] = $f_year;
        	$data['get_allmilestone'] = $this->Mportfolio->getDetails('temp_project_milestone', $c_option, '3', '', 'asc');
        	$c_option['finance_id'] = 3;

        	$data['isAssociate'] = $this->Mincharge->isAssociateUser($id, $this->session->userdata('emp_number'));
        	#$data['find_lead'] = $this->findSectorLead($sector['id']);
			#Sector User Map
			$c_option_se['inv_id'] = $id;
			$c_option_se['year'] = $year;
        	$data['business_nature_year'] = $business_nature_year = $this->Mportfolio->getDetails('port_business_year', $c_option_se);
			if($business_nature_year[0]['sector']!=''){
				$option_employee_id = $this->session->userdata['emp_number'];
				$option_partner_id = $this->session->userdata('partner_id');
				$matchCond = "(" . $business_nature_year[0]['sector'] . ") AND employee_id =" . $option_employee_id . " AND partner_id =" . $option_partner_id;
				$get_lead_se = $this->Mportfolio->get_sector_matched_assign($matchCond);
				if (!empty($get_lead_se)) {
					$data['find_lead'] = $this->session->set_userdata('sector_lead', '1');
				} else {
					$data['find_lead'] = $this->session->set_userdata('sector_lead', '0');
				}
			}else{
				$data['find_lead'] = $this->findSectorLead($sector['id']);
			}
			#Sector User Map

        	$status = 3;
        	$qual_option['module_id'] = 8;
        	if ($data['isAssociate'] == 1 || $this->session->userdata['user_type'] == 'admin' || $this->session->userdata['user_type'] == 'superadmin') {
        		$data['fund_data'] = $this->Mportfolio->getDetails('temp_finance_fundraise', $c_option, '', $f_year);
        		$data['qualitative_data'] = $this->Mportfolio->getDetails('temp_qualitative_data', $qual_option, $status, $f_year);
        	} else if ($this->session->userdata['sector_lead'] == 1 && count($data['dataConfig']['fundCount']) > 0) {
        		$data['fund_data'] = $this->Mportfolio->getDetails('temp_finance_fundraise', $c_option, '', $f_year);
        		$data['qualitative_data'] = $this->Mportfolio->getDetails('temp_qualitative_data', $qual_option, $status, $f_year);
        	} else {
        		$data['fund_data'] = $this->Mportfolio->getDetails('port_finance_fundraise', $c_option, '1', $f_year);
        		$data['qualitative_data'] = $this->Mportfolio->getDetails('port_qualitative_data', $qual_option, '1', $f_year);
        	}

        	$data['approvals'] = $approvals = $this->Mportfolio->getDetails('port_config_approval', $appoption);
        	$this->session->set_userdata('fundraise_approval', $approvals[0]['fundraise_approval']);
        	$pending = '0';
        	if ($year == '') {
        		if ($this->session->userdata['sector_lead'] == 1) {
        			$get_data = $this->Mportfolio->getConfigApprovalDetails('port_config_approval', $config_option, 'fundraise_approval');
        			if (count($get_data) > 0) {
        				redirect('portfolio/fundraise/' . $id . '/' . $get_data[0]['financial_year']);
        			}
        		}
        	}
        	$business_nature = $this->Mportfolio->getSecEmpId($id);
        	$dd_company = $this->Mportfolio->getSecEmployee_DD($id);
        	$incubation_app = $this->Mportfolio->getSecEmployee_app($id);
        	#$get_port_leadID = isset($business_nature[0]['employee_id']) && $business_nature[0]['employee_id'] != '' ? $business_nature[0]['employee_id'] : $dd_company[0]['employee_id'];
			$get_port_leadID ='';
			$employeeIds = array();
			if(!empty($business_nature[0]['employee_id'])){ 
				foreach ($business_nature as $element) {
					$employeeIds[] = $element['employee_id'];
				}
				$get_port_leadID = implode(', ', $employeeIds);
			}else{
				$get_port_leadID =  $dd_company['employee_id'];
			} 
        	$get_sect_leadID = isset($get_port_leadID) && $get_port_leadID != '' ? $get_port_leadID : $incubation_app[0]['employee_id'];
        	$data['sector_lead'] = $this->Mportfolio->getEmpDetailsById($get_sect_leadID);
        	$data['get_month_list'] = $this->month();

        	$this->load->vars($data);
        	$this->load->view('portfolio/incubatee_plan/fundraise');
        }

