        			$main_data['edited_status'] = 0;
        			$m_query = $this->Mportfolio->updatePortfolioDetail('port_finance_fundraise', $main_data, $option);
        		} else {
        			$edited['edited_status'] = 1;
        			$m_query = $this->Mportfolio->updatePortfolioDetail('port_finance_fundraise', $edited, $option);
        		}
        		$t_query = $this->Mportfolio->updatePortfolioDetail('temp_finance_fundraise', $data, $option);
        	} else {
        		$data['created_by'] = $this->session->userdata('emp_number');
        		$data['created_at'] = date("Y-m-d H:i:s");
        		$m_query = $this->Mportfolio->insertPortfolioDetail('port_finance_fundraise', $data);
        		$t_query = $this->Mportfolio->insertPortfolioDetail('temp_finance_fundraise', $data);
        	}

        	if ($t_query) {
        		$checkExist1 = $this->Mportfolio->getDetails('port_config_approval', $app_option);
        		if (count($checkExist1) > 0) {
        			$query1 = $this->Mportfolio->updatePortfolioDetail('port_config_approval', $approval, $app_option);
        		} else {
        			$query1 = $this->Mportfolio->insertPortfolioDetail('port_config_approval', $approval);
        		}
        		$this->session->set_flashdata('successMsg', "$title details saved successfully");
        	} else {
        		$this->session->set_flashdata('errormsg', 'Value Missing');
        	}
        	$lightBox = $_POST['updatePlan'];
        	if ($lightBox == 1) {
        		$this->session->set_userdata('plan_lightbox', 1);
        		redirect("portfolio/$page/" . $_POST['innovation_id'] . '/' . $_POST['cur_finance']);
        	} else {
        		$this->session->set_userdata('plan_lightbox', 0);
        		redirect("portfolio/$rdir/" . $_POST['innovation_id'] . '/' . $_POST['cur_finance']);
        	}
        }

