        	$data = array();
        	$mod = isset($_POST['module']) ? $_POST['module'] : '';
        	$option['id'] = $check['id'] = $_POST['milestone_edit_id'];
        	$approval_status = isset($_POST['approvalStatus']) ? $_POST['approvalStatus'] : '0';
        	$option['inv_id'] = $app_option['inv_id'] = $approval['inv_id'] = $data['inv_id'] = $_POST['innovation_id'];
        // $option['financial_year'] = $app_option['financial_year'] = $approval['financial_year'] = $data['financial_year'] = $_POST['cur_finance'];
        	$data['name'] = $_POST['milestone_name'];

        	if ($this->session->userdata['sector_lead'] == 11 || $approval_status == 1) {
        		$data['status'] = 1;
        		$approval['project_approval'] = 3;
        	} else {
        		$data['status'] = 0;
        		$approval['project_approval'] = 1;
        		$approval['config_approval'] = 1;
        	}

        	$checkExist = $this->Mportfolio->getDetails('port_project_milestone', $check);
        	if (count($checkExist) > 0 && $checkExist[0]['status'] == 0) {
        		$data['updated_by'] = $this->session->userdata('emp_number');
        		$m_query = $this->Mportfolio->updatePortfolioDetail('port_project_milestone', $data, $option);
        		$t_query = $this->Mportfolio->updatePortfolioDetail('temp_project_milestone', $data, $option);
        		$mile_id = $_POST['milestone_edit_id'];
        	} else if (count($checkExist) > 0 && $checkExist[0]['status'] == 1) {
        		$data['updated_by'] = $this->session->userdata('emp_number');
        		if ($this->session->userdata['sector_lead'] == 11 || $approval_status == 1) {
        			$main_data = $data;
        			$main_data['edited_status'] = 0;
        			$m_query = $this->Mportfolio->updatePortfolioDetail('port_project_milestone', $main_data, $option);
        		} else {
        			$edited['edited_status'] = 1;
        			$m_query = $this->Mportfolio->updatePortfolioDetail('port_project_milestone', $edited, $option);
        		}
        		$t_query = $this->Mportfolio->updatePortfolioDetail('temp_project_milestone', $data, $option);
        		$mile_id = $_POST['milestone_edit_id'];
        	} else {
        		$data['created_by'] = $this->session->userdata('emp_number');
        		$data['created_at'] = date("Y-m-d H:i:s");
        		$m_query = $this->Mportfolio->insertPortfolioDetail('port_project_milestone', $data);
        		$t_query = $this->Mportfolio->insertPortfolioDetail('temp_project_milestone', $data);
        		$mile_id = $this->db->insert_id();
        	}

        	if ($t_query) {
        		$checkExist1 = $this->Mportfolio->getDetails('port_config_approval', $app_option);
        		if (count($checkExist1) > 0) {
        			$query1 = $this->Mportfolio->updatePortfolioDetail('port_config_approval', $approval, $app_option);
        		} else {
        			$partner_id = $this->session->userdata('partner_id');
        			$data['fin_year'] = $this->Mportfolio->getAllFinancialYear($partner_id);
        			$approval['financial_year'] = date('Y');
        			foreach ($data['fin_year'] as $fy) {
        				if ($fy['status'] == 1) {
        					$approval['financial_year'] = $fy['fin_year'];
        				}
        			}
        			$query1 = $this->Mportfolio->insertPortfolioDetail('port_config_approval', $approval);
        		}
        		$this->session->set_flashdata('successMsg', "Milestone title saved successfully");
        	} else {
        		$this->session->set_flashdata('errormsg', 'Value Missing');
        	}
        	if ($mod != '' && $mod == 'plan') {
        		redirect($_SERVER['HTTP_REFERER']);
        	} else if ($mod != '' && $mod == 'allforms') {
        		redirect($_SERVER['HTTP_REFERER']);
        	} else {
        		redirect('portfolio/milestone/' . $_POST['innovation_id'] . '/' . $_POST['milefy'] . '/' . $mile_id);
        	}
        }

