        public function getTaskdetails() {
        	$task['id'] = $proj['task_id'] = $_POST['taskid'];
        	$get_task = $this->Mportfolio->getDetails('temp_project_task', $task);
        	$get_project = $this->Mportfolio->getDetails('temp_project_details', $proj);
        	$result['task_id'] = $get_task[0]['id'];
