        		$miles['created_by'] = $this->session->userdata('emp_number');
        		$miles['created_at'] = date("Y-m-d H:i:s");
        		$query1 = $this->Mportfolio->insertPortfolioDetail('port_project_milestone', $miles);
        		$query2 = $this->Mportfolio->insertPortfolioDetail('temp_project_milestone', $miles);
        		$task['milestone_id'] = $tcheck['milestone_id'] = $proj['milestone_id'] = $this->db->insert_id();
        	}

        	$checkExist1 = $this->Mportfolio->getDetails('port_config_approval', $app_option);
        	if (count($checkExist1) > 0) {
        		$query1 = $this->Mportfolio->updatePortfolioDetail('port_config_approval', $approval, $app_option);
        	} else {
        		$partner_id = $this->session->userdata('partner_id');
        		$data['fin_year'] = $this->Mportfolio->getAllFinancialYear($partner_id);
        		$approval['financial_year'] = date('Y');
        		foreach ($data['fin_year'] as $fy) {
        			if ($fy['status'] == 1) {
        				$approval['financial_year'] = $fy['fin_year'];
        			}
        		}
        		$query1 = $this->Mportfolio->insertPortfolioDetail('port_config_approval', $approval);
        	}

        	$checkExist = $this->Mportfolio->getDetails('port_project_task', $tcheck);
        	if (count($checkExist) > 0 && $checkExist[0]['status'] == 0) {
        		$task['updated_by'] = $this->session->userdata('emp_number');
        		$m_query = $this->Mportfolio->updatePortfolioDetail('port_project_task', $task, $tcheck);
        		$t_query = $this->Mportfolio->updatePortfolioDetail('temp_project_task', $task, $tcheck);
        	} else if (count($checkExist) > 0 && $checkExist[0]['status'] == 1) {
        		$task['updated_by'] = $this->session->userdata('emp_number');
        		if ($this->session->userdata['sector_lead'] == 11 || $approval_status == 1) {
        			$main_data = $task;
        			$main_data['edited_status'] = 0;
        			$m_query = $this->Mportfolio->updatePortfolioDetail('port_project_task', $main_data, $tcheck);
        		} else {
        			$edited['edited_status'] = 1;
        			$m_query = $this->Mportfolio->updatePortfolioDetail('port_project_task', $edited, $tcheck);
        		}
        		$t_query = $this->Mportfolio->updatePortfolioDetail('temp_project_task', $task, $tcheck);
        	} else {
        		$task['created_by'] = $this->session->userdata('emp_number');
        		$task['created_at'] = date("Y-m-d H:i:s");
        		$m_query = $this->Mportfolio->insertPortfolioDetail('port_project_task', $task);
        		$t_query = $this->Mportfolio->insertPortfolioDetail('temp_project_task', $task);
        		$proj['task_id'] = $this->db->insert_id();
        	}

        	$check = $this->Mportfolio->getDetails('port_project_details', $option);
        	if (count($check) > 0 && $check[0]['status'] == 0) {
        		$proj['updated_by'] = $this->session->userdata('emp_number');
        		$md_query = $this->Mportfolio->updatePortfolioDetail('port_project_details', $proj, $option);
        		$td_query = $this->Mportfolio->updatePortfolioDetail('temp_project_details', $proj, $option);
        	} else if (count($check) > 0 && $check[0]['status'] == 1) {
        		$proj['updated_by'] = $this->session->userdata('emp_number');
        		if ($this->session->userdata['sector_lead'] == 11 || $approval_status == 1) {
        			$main_data = $proj;
        			$main_data['edited_status'] = 0;
        			$md_query = $this->Mportfolio->updatePortfolioDetail('port_project_details', $main_data, $option);
        		} else {
        			$edited['edited_status'] = 1;
        			$md_query = $this->Mportfolio->updatePortfolioDetail('port_project_details', $edited, $option);
        		}
        		$td_query = $this->Mportfolio->updatePortfolioDetail('temp_project_details', $proj, $option);
        	} else {
        		$proj['created_by'] = $this->session->userdata('emp_number');
        		$proj['created_at'] = date("Y-m-d H:i:s");
        		$md_query = $this->Mportfolio->insertPortfolioDetail('port_project_details', $proj);
        		$td_query = $this->Mportfolio->insertPortfolioDetail('temp_project_details', $proj);
        	}

        	if ($td_query) {
        		$this->session->set_flashdata('successMsg', "Milestone details saved successfully");
        	} else {
        		$this->session->set_flashdata('errormsg', 'Value Missing');
        	}
        	$lightBox = $_POST['updatePlan'];
        	if ($lightBox == 1) {
        		$this->session->set_userdata('plan_lightbox', 1);
        	} else {
        		$this->session->set_userdata('plan_lightbox', 0);
        	}
        	if ($mod != '' && $mod == 'plan') {
        		redirect('portfolio/pending_inputs/milestone_plan/' . $_POST['proj_innovation_id'] . '/' . $_POST['proj_milestone_id']);
        	} else if ($mod != '' && $mod == 'allforms') {
        		redirect('portfolio/all_forms/milestone/' . $_POST['proj_innovation_id'] . '/' . $_POST['projfy'] . '/' . $_POST['proj_milestone_id']);
        	} else {
        		redirect('portfolio/milestone/' . $_POST['proj_innovation_id'] . '/' . $_POST['projfy'] . '/' . $proj['milestone_id']);
        	}
        }

        public function configCount($id, $f_year = '') {
        	if ($id != '')
        		check_partner_privilege($id);

        	$product['inv_id'] = $sales['inv_id'] = $channel['inv_id'] = $pipe['inv_id'] = $revenue['inv_id'] = $profit['inv_id'] = $vif['inv_id'] = $id;
        	$fund['inv_id'] = $mentor['inv_id'] = $tap['inv_id'] = $nontap['inv_id'] = $dp['inv_id'] = $board['inv_id'] = $team['inv_id'] = $impact['inv_id'] = $project['inv_id'] = $id;

        	if ($f_year != '') {
        		$product['financial_year'] = $sales['financial_year'] = $channel['financial_year'] = $pipe['financial_year'] = $revenue['financial_year'] = $profit['financial_year'] = $vif['financial_year'] = $f_year;
        		$fund['financial_year'] = $mentor['financial_year'] = $tap['financial_year'] = $nontap['financial_year'] = $dp['financial_year'] = $board['financial_year'] = $team['financial_year'] = $impact['financial_year'] = $project['financial_year'] = $f_year;
        	}

        	$product['product_approval'] = $sales['sales_approval'] = $channel['channel_approval'] = $pipe['pipeline_approval'] = $revenue['revenue_approval'] = $profit['netprofit_approval'] = $vif['vif_approval'] = 2;
        	$fund['fundraise_approval'] = $mentor['mentor_approval'] = $tap['tap_approval'] = $nontap['nontap_approval'] = $dp['dp_approval'] = $board['board_approval'] = $team['team_approval'] = $impact['impact_approval'] = $project['project_approval'] = 2;

        	$data['productCount'] = $this->Mportfolio->getDetails('port_config_approval', $product);
        	$data['salesCount'] = $this->Mportfolio->getDetails('port_config_approval', $sales);
        	$data['channelCount'] = $this->Mportfolio->getDetails('port_config_approval', $channel);
        	$data['pipeCount'] = $this->Mportfolio->getDetails('port_config_approval', $pipe);
        	$data['revenueCount'] = $this->Mportfolio->getDetails('port_config_approval', $revenue);
        	$data['netCount'] = $this->Mportfolio->getDetails('port_config_approval', $profit);
        	$data['vifCount'] = $this->Mportfolio->getDetails('port_config_approval', $vif);
        	$data['fundCount'] = $this->Mportfolio->getDetails('port_config_approval', $fund);
        	$data['mentorCount'] = $this->Mportfolio->getDetails('port_config_approval', $mentor);
        	$data['tapCount'] = $this->Mportfolio->getDetails('port_config_approval', $tap);
        	$data['nontapCount'] = $this->Mportfolio->getDetails('port_config_approval', $nontap);
        	$data['dpCount'] = $this->Mportfolio->getDetails('port_config_approval', $dp);
        	$data['boardCount'] = $this->Mportfolio->getDetails('port_config_approval', $board);
        	$data['teamCount'] = $this->Mportfolio->getDetails('port_config_approval', $team);
        	$data['impactCount'] = $this->Mportfolio->getDetails('port_config_approval', $impact);
        	$data['projectCount'] = $this->Mportfolio->getDetails('port_config_approval', $project);

        	return $data;
        }

