        public function portfolio_summary($year = '') {
        	if ($this->session->userdata['partner_id'] == '2') {
        		redirect('portfolio/portfolio_summary_old');
        	}
        	if ($this->session->userdata['role_id'] == '4') {
        		$partner_id = $this->session->userdata('partner_id');
        		$sector_access = $this->session->userdata['sectorAccess'];
        		$data['fin_year'] = $this->Mportfolio->getAllFinancialYear($partner_id);
        		$get_sector_company = $this->Mportfolio->getCustomSectorCompany($sector_access, $data['fin_year'][0]['fin_year']);
        		redirect('portfolio/company_summary/' . $get_sector_company[0]['id']);
        	} else {
        		$emp_id = $option['employee_id'] = $this->session->userdata['emp_number'];
        		$partner_id = $option['partner_id'] = $this->session->userdata('partner_id');
        		$option1['associate_employee'] = $emp_id;
        		$status1 = 1;
        		$assign_list = $this->Mportfolio->getListingDetails('assign_associate', $option1, $status1);
        		foreach ($assign_list as $lists) {
        			$asslist[] = $lists['innovation'];
        		}

        		$get_lead = $this->Mportfolio->getDetails('assign_sector_lead', $option);
        		$get_assigned_sector = $this->Mportfolio->getAssignedSectorDetails($emp_id);
        		$sector = $assign = $unique_assigned = $filter_assigned = array();
        		foreach ($get_assigned_sector as $assign_sec) {
        			array_push($sector, $assign_sec['sector']);
        		}

        		foreach ($get_lead as $lead) {
        			array_push($sector, $lead['sector_id']);
        			array_push($assign, $lead['employee_id']);
        		}
        		$unique_assigned = array_unique($sector);
        		$remove_empty = array_filter($unique_assigned);
        		$filter_assigned = array_values($remove_empty);
//            $data['default_sector'] = $filter_assigned[0];
        		$get_sector_name = $this->Minnovation->getSectorNamePitch($filter_assigned[0]);
        		$data['default_sector_name'] = $get_sector_name[0]['sector'];
        		$data['fin_year'] = $this->Mportfolio->getAllFinancialYear($partner_id);
            // $data['sectors_values'] = $this->Mincharge->getSectorNames($partner_id);
        		$get_inc_sector = $this->Mportfolio->getIncSector();
        		$inc_sectors = array();
        		foreach ($get_inc_sector as $sect) {
        			array_push($inc_sectors, $sect['sector']);
        		}
        		if (count(array_intersect($filter_assigned, $inc_sectors)) === 0) {
        			$data['default_sector'] = '';
        		} else {
                // There is at least one value from array1 present in array2
        			$def_sec = array_intersect($filter_assigned, $inc_sectors);
        			$data['default_sector'] = $def_sec[0];
        		}
        		$merge_incs = implode(',', $inc_sectors);

        		$data['sectors_values'] = $this->Mportfolio->getIncSectorNames($merge_incs);
//        $data['upcoming_meetings'] = $this->Mportfolio->getUpcomingBoardMeetings();
        		if (count($asslist) > 0) {
        			$assigned_inv = rtrim(implode(',', $asslist), ',');
        		} else {
        			$assigned_inv = '0';
        		}
        		$data['assignlist'] = $asslist;
        		$data['upcoming_milestone'] = $this->Mportfolio->getPortUpcomingMilestones($assigned_inv, 10);
        		if ($year == '') {
        			if (isset($data['fin_year'][0]['fin_year']) && $data['fin_year'][0]['fin_year'] != '') {
        				foreach ($data['fin_year'] as $fy) {
        					if ($fy['status'] == 1) {
        						$data['current_fy'] = $fy['fin_year'];
        					}
        				}
        			} else {
        				$data['current_fy'] = date('Y');
        			}
        		} else {
        			$data['current_fy'] = $year;
        		}
        		$summ_fy = $data['current_fy'];
        		$data['company_list'] = $this->Mportfolio->getSummaryDetails('innovation_pool', $data['default_sector'], $summ_fy);

        		$pemp_option['emp_id'] = $this->session->userdata('emp_number');
        		$checkExist = $this->Mportfolio->getDetails('hr_user_login', $pemp_option);
        		if ($checkExist[0]['enc_user_key'] != '') {
        			$data['enc_user_key'] = $checkExist[0]['enc_user_key'];
        		} else {
        			$data['enc_user_key'] = "";
        		}

        		$this->load->vars($data);
        		$this->load->view('portfolio/portfolio_summary_new');
        	}
        }

