        public function portfolio_incubatees() {	#echo'<pre>';print_r($_POST);die;
			
        	$inc_sector = $this->input->post('sector');
        	$inc_year = $this->input->post('year');
        	if ($this->session->userdata('role_id') == '4') {
        		$sector_access = isset($inc_sector) && $inc_sector != '' ? $inc_sector : $this->session->userdata['sectorAccess'];
				#CR QUERY
        		$company_list = $this->Mportfolio->getCustomSectorCompany($sector_access, $inc_year);
        	} else {
        		$company_list = $this->Mportfolio->getSummaryDetails('innovation_pool', $inc_sector, $inc_year);
        	}
			#echo'<pre>';print_r($company_list);die;
        	$option['associate_employee'] = $this->session->userdata['emp_number'];
        	$status = 1;
        	$assign_list = $this->Mportfolio->getListingDetails('assign_associate', $option, $status);
        	foreach ($assign_list as $lists) {
        		$asslist[] = $lists['innovation'];
        	}

        	$curr_user_inv = array(); 
        	$other_user_inv = array();
        	$exited_inv = $graduated_inv = array();
        	$i = 0;
			
			$get_port_company_merge  = $this->Mportfolio->get_all_data('port_company_merge', array('status'=>1));
			$get_inv_id_merge = array();
			if(!empty($get_port_company_merge)){
				$get_inv_id_merge = array_column($get_port_company_merge,'current_inv_id');
			}
			
        	foreach ($company_list as $company) {
				if($company['id']!='289202'){
        		$comp_yr = $company['exit_year'];
        		if ($company['exit_month'] == 01 || $company['exit_month'] == 02 || $company['exit_month'] == 03) {
        			$comp_yr = $company['exit_year'] - 1;
        		}
				if(!in_array($company['id'],$get_inv_id_merge)){
					if ($company['company_status'] == 3) {
						if ($comp_yr == '0000' || ($inc_year <= $comp_yr)) {
							$exited_inv[$i]['id'] = $company['id'];
							$exited_inv[$i]['name_of_enterprise'] = $company['name_of_enterprise'];
							$exited_inv[$i]['company_status'] = $company['company_status'];
							$exited_inv[$i]['emp_id'] = $company['emp_id'];
							$exited_inv[$i]['exit_year'] = $company['exit_year'];
							$exited_inv[$i]['comp_yr'] = $comp_yr;
						}
					} else if ($company['company_status'] == 2) {
						if ($comp_yr == '0000' || ($inc_year <= $comp_yr)) {
							$graduated_inv[$i]['id'] = $company['id'];
							$graduated_inv[$i]['name_of_enterprise'] = $company['name_of_enterprise'];
							$graduated_inv[$i]['company_status'] = $company['company_status'];
							$graduated_inv[$i]['emp_id'] = $company['emp_id'];
							$graduated_inv[$i]['exit_year'] = $company['exit_year'];
							//$exited_inv[$i]['comp_yr'] = $comp_yr;
						}
					} else {
						if (in_array($company['id'], $asslist)) {
							$curr_user_inv[$i]['id'] = $company['id'];
							$curr_user_inv[$i]['name_of_enterprise'] = $company['name_of_enterprise'];
							$curr_user_inv[$i]['company_status'] = $company['company_status'];
							$curr_user_inv[$i]['emp_id'] = $company['emp_id'];
							$curr_user_inv[$i]['exit_year'] = $company['exit_year'];
						} else {
							$other_user_inv[$i]['id'] = $company['id'];
							$other_user_inv[$i]['name_of_enterprise'] = $company['name_of_enterprise'];
							$other_user_inv[$i]['company_status'] = $company['company_status'];
							$other_user_inv[$i]['emp_id'] = $company['emp_id'];
							$other_user_inv[$i]['exit_year'] = $company['exit_year'];
						}
					}
					$i++;
				}
				}
        	}
        	$companies = array_merge($curr_user_inv, $other_user_inv);
        	$graduted = array_merge($companies, $graduated_inv);
        	$data['incubatee_list'] = array_merge($graduted, $exited_inv);
        	echo json_encode($data);
        }
		
		
