							$other_user_inv[$i]['company_status'] = $company['company_status'];
							$other_user_inv[$i]['emp_id'] = $company['emp_id'];
							$other_user_inv[$i]['exit_year'] = $company['exit_year'];
						}
					}
					$i++;
				}
				}
        	}
        	$companies = array_merge($curr_user_inv, $other_user_inv);
        	$graduted = array_merge($companies, $graduated_inv);
        	$data['incubatee_list'] = array_merge($graduted, $exited_inv);
        	echo json_encode($data);
        }



        public function company_summary($id = '', $year = '') {
        	if ($id != '')
        		check_partner_privilege($id);
        	$option['id'] = $c_option['inv_id'] = $data['innovation_id'] = $id;
        	$emp_id = $option['employee_id'] = $this->session->userdata['emp_number'];
        	$option1['associate_employee'] = $emp_id;
        	$status1 = 1;
        	$assign_list = $this->Mportfolio->getListingDetails('assign_associate', $option1, $status1);
        	foreach ($assign_list as $lists) {
        		$asslist[] = $lists['innovation'];
        	}
        // $port_sector = "<script>document.write(localStorage.getItem('port_sector'));</script>";
        	$data['company_data'] = $this->Mportfolio->getDetails('port_company_data', $c_option);
        	$data['upcoming_milestone'] = $this->Mportfolio->getCompUpcomingMilestones($id, 10);

        	$data['business_nature'] = $this->Mportfolio->getDetails('port_business', $c_option);
        	$sector['id'] = isset($data['business_nature']) ? $data['business_nature'][0]['sector'] : $data['get_innovation'][0]['sector'];
        	$sector_details = $this->Mportfolio->getDetails('sector_category', $sector);

			
        	#$data['sector_name'] = $sector_details[0]['sector'];
			$getProgramArr = $this->Mportfolio->getSectorProgram('port_business_year',$year,$id);
			if($getProgramArr[0]['sector']!=''){
				$getSectorID = explode(',',$getProgramArr[0]['sector']);
				$getProgramListArr = $this->Mportfolio->getSectorIn($getSectorID); 
				$sector_nameArr = array_column($getProgramListArr,'sector');
				$sector_name = implode(',',$sector_nameArr);
				if($sector_name!=''){
					$data['sector_name'] = $sector_name;		
				}else{
					$data['sector_name'] = $sector_details[0]['sector'];
				}
			}else{
				$data['sector_name'] = $sector_details[0]['sector'];
			}

        	$data['assignlist'] = $asslist;
        	$partner_id = $this->session->userdata('partner_id');
        	$data['fin_year'] = $this->Mportfolio->getAllFinancialYear($partner_id);

        	if ($year == '') {
        		if (isset($data['fin_year'][0]['fin_year']) && $data['fin_year'][0]['fin_year'] != '') {
        			foreach ($data['fin_year'] as $fy) {
        				if ($fy['status'] == 1) {
        					$data['current_fy'] = $fy['fin_year'];
        				}
        			}
        		} else {
        			$data['current_fy'] = date('Y');
        		}
        	} else {
        		$data['current_fy'] = $year;
        	}
        	$summ_fy = $data['current_fy'];
        	$data['upcoming_meeting'] = $this->Mportfolio->getCompDPMeeting($id, 10, $summ_fy);
        	if ($this->session->userdata('role_id') == '4') {
        		$data['default_sector'] = $sector_id = isset($_POST['sec_id']) && $_POST['sec_id'] != '' ? $_POST['sec_id'] : $this->session->userdata('sectorAccess');
        		$data['current_fy'] = isset($_POST['f_year']) && $_POST['f_year'] != '' ? $_POST['f_year'] : $summ_fy;
        		$data['company_list'] = $this->Mportfolio->getCustomSectorCompany($sector_id, $summ_fy);
        		$sec_cond = "id IN ($sector_id)";
        		$data['sectors_values'] = $this->Mportfolio->getMultiSector($sec_cond);
        	} else {
        		$data['company_list'] = $this->Mportfolio->getSummaryDetails('innovation_pool', $sector['id'], $summ_fy);
        	}
        	$data['approved_sales'] = $this->Mportfolio->getSalesMaster('port_sales_data', $c_option, $summ_fy, '1');
        	$this->load->vars($data);
        	$this->load->view('portfolio/company_summary');
        }

        public function custom_company_summary($id = '', $year = '') {
        	$partner_id = $this->session->userdata('partner_id');
        	$fin_year = $this->Mportfolio->getAllFinancialYear($partner_id);
        	$sector_id = isset($_POST['sec_id']) && $_POST['sec_id'] != '' ? $_POST['sec_id'] : $this->session->userdata('sectorAccess');
        	$fyear = isset($_POST['f_year']) && $_POST['f_year'] != '' ? $_POST['f_year'] : $fin_year[0]['fin_year'];
