        	$data['company'] = $get_sector_company[0]['id'];
        	$data['fyear'] = $fyear;
        	echo json_encode($data);
        }

        function assessment_export() {
        	$this->load->library('Excel');
        	$objPHPExcel = new PHPExcel();
        	$objPHPExcel->getProperties()->setCreator("Villgro")
        	->setLastModifiedBy("Villgro")
        	->setTitle("Documents Master List")
        	->setSubject("Documents Master List")
        	->setDescription("Documents Master List")
        	->setKeywords("office 2007 openxml php")
        	->setCategory("Documents Master List");

        	$cond = "(IP.partner_id = '1' or IP.partner_id ='01') and IP.status != '11'";
        	$this->db->select('IP.id, IP.name_of_enterprise, IP.sector,SC.sector as sector_name,IP.stage,IP.status, pitch.submitted_date as pitch_submitted_date,asst.score');
        	$this->db->join('sector_category SC', 'SC.id =  IP.sector', 'left');
        	$this->db->join('inv_user INV', 'INV.inv_no = IP.innovation_id', 'left');
        	$this->db->join('pitch_user pitch', 'pitch.inno_id = IP.innovation_id', 'left');
        	$this->db->join('assest_detail asst', 'asst.innovation_id = IP.id', 'left');
        	$this->db->distinct();
        	$this->db->from('innovation_pool IP');
        	$this->db->where(array("IP.program" => '3', "pitch.submitted_date >=" => '2018-08-01 00:00:00', "pitch.submitted_date <=" => '2019-09-05 00:00:00', "IP.copy_status !=" => '4'));
        	$this->db->where($cond);
        	$query = $this->db->get();
        	$rows = $query->result_array();
        	$styletitle = array(
        		'font' => array(
        			'bold' => true,
        			'color' => array('rgb' => '000000'),
        			'size' => 11,
        			'name' => 'Times New Roman',
        		),
        	);

        	$objPHPExcel->getActiveSheet()->getColumnDimension('A')->setWidth(10);
        	$objPHPExcel->getActiveSheet()->getColumnDimension('B')->setWidth(30);
        	$objPHPExcel->getActiveSheet()->getColumnDimension('C')->setWidth(20);
        	$objPHPExcel->getActiveSheet()->getColumnDimension('F')->setWidth(20);
        	$objPHPExcel->getActiveSheet()->setCellValue('A1', 'Inv Id');
        	$objPHPExcel->getActiveSheet()->setCellValue('B1', 'Enterprise name');
        	$objPHPExcel->getActiveSheet()->setCellValue('C1', 'Sector');
        	$objPHPExcel->getActiveSheet()->setCellValue('D1', 'Stage');
        	$objPHPExcel->getActiveSheet()->setCellValue('E1', 'Status');
        	$objPHPExcel->getActiveSheet()->setCellValue('F1', 'Submitted Date');
        	$objPHPExcel->getActiveSheet()->setCellValue('G1', 'Impact score');
        	$objPHPExcel->getActiveSheet()->setCellValue('H1', 'Inv score');
        	$objPHPExcel->getActiveSheet()->setCellValue('I1', 'Team score');
        	$objPHPExcel->getActiveSheet()->getStyle('A1:Y1')->applyFromArray($styletitle);
        	$i = 2;
        	foreach ($rows as $list) {
        		$score = unserialize($list['score']);
        		$stage = $this->Minnovation->getInnvationStage();
        		$status = $this->Minnovation->getInnvationStatus();
        		$objPHPExcel->getActiveSheet()->setCellValue('A' . $i, $list['id']);
        		$objPHPExcel->getActiveSheet()->setCellValue('B' . $i, $list['name_of_enterprise']);
        		$objPHPExcel->getActiveSheet()->setCellValue('C' . $i, $list['sector_name']);
        		$objPHPExcel->getActiveSheet()->setCellValue('D' . $i, $stage[$list['stage']]);
        		$objPHPExcel->getActiveSheet()->setCellValue('E' . $i, $status[$list['status']]);
        		$objPHPExcel->getActiveSheet()->setCellValue('F' . $i, $list['pitch_submitted_date']);
        		$objPHPExcel->getActiveSheet()->setCellValue('G' . $i, $score[1]);
        		$objPHPExcel->getActiveSheet()->setCellValue('H' . $i, $score[2]);
        		$objPHPExcel->getActiveSheet()->setCellValue('I' . $i, $score[6]);
        		$i++;
        	}

        	$file_name = 'assessment_score.xlsx';
        	header('Content-Type: application/vnd.ms-excel');
        	header('Content-Disposition: attachment;filename="' . $file_name . '"');
        	header('Cache-Control: max-age=0');
        	header('Cache-Control: max-age=1');

        	header('Expires: Mon, 26 Jul 1997 05:00:00 GMT');
        	header('Last-Modified: ' . gmdate('D, d M Y H:i:s') . ' GMT');
        	header('Cache-Control: cache, must-revalidate');
        	header('Pragma: public');

        	$objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel2007');
        	ob_end_clean();
        	$objWriter->save('php://output');
        	exit;
        }

        function convertMonthtoNumber($month) {
        	return date('n', strtotime($month));
        }

