							if (!isset($sums[$key])) {
								$sums[$key] = array(
									'program' => $programId,
									'program_name' => $item['program_name'],
									'inv_id' => $item['inv_id'],
									'financial_year' => $item['financial_year'],
									'month' => $item['month'],
									'year' => $item['year'],
									'sumOfAmount' => $item['amount'],
								);
							} else {
								$sums[$key]['sumOfAmount'] += $item['amount'];
