        						$indirectj_othercost += str_replace(',', '', $indirectj_other[strtolower($indirectj_othermonths[0])]);
        						$objPHPExcel->getActiveSheet()->setCellValue('AC' . $rw_inc, $indirectj_other['iris_name']);
        					}
							if($indirectj_othercost==0){
								$indirectj_othercost ='';
							}
        					$objPHPExcel->getActiveSheet()->setCellValue($monthplan[$indirectj_othermonths[0]] . $rw_inc, $indirectj_othercost);
        				}

        				foreach ($headkey_achieve as $cl => $mn) {
        					$indirectj_otheractualcost = 0;
        					$swap = array_flip($headkey_achieve);
        					foreach ($indirectj_other_actual as $indirectj_other) {
        						if ($indirectj_other['month'] == $mn) {
        							$indirect_other = str_replace(',', '', $indirectj_other['indirect_other']);
        							$indirectj_otheractualcost += $indirect_other;
        						}
        					}
							if($indirectj_otheractualcost==0){
								$indirectj_otheractualcost ='';
							}
        					$objPHPExcel->getActiveSheet()->setCellValue($swap[$mn] . $rw_inc, $indirectj_otheractualcost);
        				}
        				$rw_inc++;
        				/* impact indirect jobs other ends */

        				/* impact indirect jobs unknown details */
                    // $tap_cond[] = "t1.financial_year >= $year and t1.financial_year <= $year";
        				$impact_where = "t1.field_type = 3 and t1.gender = 4";
        				$endben_where = implode(" and ", $tap_cond);
        				$indirectj_unknown_target = $this->Mportfolio->getTargetEndbeneficiaries($endben_where, $impact_where,$sec_list);
        				$indirectj_unknown_actual = $this->Mportfolio->getActualEndbeneficiaries($endben_where,$sec_list);

        				$objPHPExcel->getActiveSheet()->setCellValue('A' . $rw_inc, $program_name);
        				$objPHPExcel->getActiveSheet()->setCellValue('B' . $rw_inc, $sector_name);
        				$objPHPExcel->getActiveSheet()->setCellValue('C' . $rw_inc, $incubs['name']);
        				$objPHPExcel->getActiveSheet()->setCellValue('D' . $rw_inc, 'Impact - Indirect Jobs - Unknown');

        				foreach ($montharr as $arrlist) {
        					$indirectj_unknownmonths = explode('-', $arrlist);
        					$indirectj_unknowncost = 0;
        					foreach ($indirectj_unknown_target as $indirectj_unknown) {
        						$indirectj_unknowncost += str_replace(',', '', $indirectj_unknown[strtolower($indirectj_unknownmonths[0])]);
        						$objPHPExcel->getActiveSheet()->setCellValue('AC' . $rw_inc, $indirectj_unknown['iris_name']);
        					}
							if($indirectj_unknowncost==0){
								$indirectj_unknowncost ='';
							}
        					$objPHPExcel->getActiveSheet()->setCellValue($monthplan[$indirectj_unknownmonths[0]] . $rw_inc, $indirectj_unknowncost);
        				}

        				foreach ($headkey_achieve as $cl => $mn) {
        					$indirectj_unknownactualcost = 0;
        					$swap = array_flip($headkey_achieve);
        					foreach ($indirectj_unknown_actual as $indirectj_unknown) {
        						if ($indirectj_unknown['month'] == $mn) {
        							$indirect_unknown = str_replace(',', '', $indirectj_unknown['indirect_unknown']);
        							$indirectj_unknownactualcost += $indirect_unknown;
        						}
        					}
							if($indirectj_unknownactualcost==0){
								$indirectj_unknownactualcost ='';
							}
        					$objPHPExcel->getActiveSheet()->setCellValue($swap[$mn] . $rw_inc, $indirectj_unknownactualcost);
        				}
        				$rw_inc++;
        				/* impact unknown indirect jobs ends */

        				/* impact metrics male details */
                    // $tap_cond[] = "t1.financial_year >= $year and t1.financial_year <= $year";
        				$impact_where = "t1.field_type = 4";
                    // $endben_where = implode(" and ", $tap_cond);
        				$metric_target = $this->Mportfolio->getTargetEndbeneficiaries($endben_where, $impact_where,$sec_list);


        				foreach ($montharr as $arrlist) {
        					$met_inc = $rw_inc;
        					$metricmonths = explode('-', $arrlist);
        					$metriccost = 0;
        					foreach ($metric_target as $metric) {
								
								$getMetricsData = $this->Mportfolio->getDetails('master_metrics', array('id'=>$metric['metric_name']));
								$metricName = '';
								if($getMetricsData){
									$metricName = $getMetricsData[0]['name'];
								}
        						$objPHPExcel->getActiveSheet()->setCellValue('A' . $met_inc, $program_name);
        						$objPHPExcel->getActiveSheet()->setCellValue('B' . $met_inc, $sector_name);
        						$objPHPExcel->getActiveSheet()->setCellValue('C' . $met_inc, $incubs['name']);
        						$objPHPExcel->getActiveSheet()->setCellValue('D' . $met_inc, 'Metric - ' . $metricName);
        						$metriccost = str_replace(',', '', $metric[strtolower($metricmonths[0])]);
        						$metric_actual = $this->Mportfolio->getActualMetric($endben_where, $metric['id']);
						
        						foreach ($headkey_achieve as $cl => $mn) {
        							$metricactualcost = 0;
        							$swap = array_flip($headkey_achieve);
        							foreach ($metric_actual as $metric_act) {
        								if ($metric_act['month'] == $mn) {
        									$metricactualcost += $metric_act['metric_value'];
        								}
        							}
									if($metricactualcost==0){
										$metricactualcost ='';
									}
        							$objPHPExcel->getActiveSheet()->setCellValue($swap[$mn] . $met_inc, $metricactualcost);
        						}
								if($metriccost==0){
										$metriccost ='';
								}
        						$objPHPExcel->getActiveSheet()->setCellValue($monthplan[$metricmonths[0]] . $met_inc, $metriccost);
        						$objPHPExcel->getActiveSheet()->setCellValue('AC' . $met_inc, $metric['iris_name']);
        						$met_inc++;
        					}
        				}
        				$rw_inc += count($metric_target);
        				/* impact metrics male ends */
        			}
        		}
        	}						
	

        	if ($sector_id != 'all') {
				$sectorList  = $this->Mportfolio->get_all_data('sector_category', array('id'=>$sector_id));
				#echo'<pre>';print_r($programList);die;
        		$sname = (str_replace(' ', '_', strtolower($sectorList[0]->sector)));
        	} else {
        		$sname = 'Allsector';
        	}
			#echo '123456';die;
        	 $file_name = preg_replace('/[^A-Za-z0-9\_]/', '', $sname) . '.xlsx'; 
			header('Content-Type: application/vnd.ms-excel'); 
        	header('Content-Disposition: attachment;filename="' . $file_name . '"');
        	header('Cache-Control: max-age=0');
        	header('Cache-Control: max-age=1');

        	header('Expires: Mon, 26 Jul 1997 05:00:00 GMT');
        	header('Last-Modified: ' . gmdate('D, d M Y H:i:s') . ' GMT');
        	header('Cache-Control: cache, must-revalidate');
        	header('Pragma: public');

        	$objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel2007');
        	ob_end_clean();

        	$objWriter->save('php://output');
        	exit;
        }

