    public function plan_updates($id = '', $month = '') {
    	if ($id != '')
    		check_partner_privilege($id);
    	$c_option['inv_id'] = $net_option['inv_id'] = $inv_id['inv_id'] = $data['innovation_id'] = $id;

    	$data['plan_header'] = $this->plan_header($id);
    	$partner_id = $this->session->userdata('partner_id');
    	$data['fin_year'] = $this->Mportfolio->getAllFinancialYear($partner_id);
    	$f_year = date('Y');
    	foreach ($data['fin_year'] as $fy) {
    		if ($fy['status'] == 1) {
    			$f_year = $fy['fin_year'];
    		}
    	}
    	$c_option['finance_id'] = 1;
    	$revenue_data = $this->Mportfolio->getDetails('port_finance_fundraise', $c_option, '', $f_year);

    	$net_option['finance_id'] = 2;
    	$net_data = $this->Mportfolio->getDetails('port_finance_fundraise', $net_option, '', $f_year);

    	$rev_total = $net_total = 0;

    	$r_data = json_decode($revenue_data[0]['data'], true);
    	foreach ($r_data as $value) {
    		$rev_total = $rev_total + $value;
    	}

    	$n_data = json_decode($net_data[0]['data'], true);
    	foreach ($n_data as $value) {
    		$net_total = $net_total + $value;
    	}
    	$data['plan_revenue'] = $rev_total;
    	$data['plan_profit'] = $net_total;

    	$cur_month = date('M');
    	$getmonth = $this->month();
    	$actualMonth = $this->actual_month();
    	$arr = array_search($cur_month, $getmonth);

    	for ($i = ($arr - 1); $i >= 0; $i--) {
    		$derivemonth[] = array_search($getmonth[$i], $actualMonth);
    		$monthName[] = $getmonth[$i];
    	}

    	$least_month = implode(', ', $derivemonth);
    	$get_monthCount = $this->Mportfolio->getUpdatesCount('plan_updates', $least_month, $f_year);

    	foreach ($get_monthCount as $val) {
    		if (in_array($val['month'], $derivemonth)) {
    			$key = array_search($val['month'], $derivemonth);
    			unset($derivemonth[$key]);
    			unset($monthName[$key]);
    		}
    	}

    	if ($month == '') {
    		$month = date('n') - 1;
    	}

    	$status = $limit = 3;
    	$plan['inv_id'] = $id;
    	$plan['month'] = $month;
    	$data['current_month'] = $month;
    	$data['current_financial'] = $f_year;
    	$data['pending_month'] = array_reverse($monthName);
    	$data['milestone'] = $this->Mportfolio->getPlanDetails('port_project_milestone', $inv_id, $month, $f_year, $status, $limit);
    	$data['updates'] = $this->Mportfolio->getPlanDetails('plan_updates', $plan, '', $f_year, $status);

    	$this->load->vars($data);
    	$this->load->view('portfolio/pending_inputs/plan_updates');
    }

