    public function chartD3() {
    	$id = $this->input->post('id');
    	$quarter = $this->input->post('quarter');
    	$startDate = $this->input->post('startDate');
    	$endDate = $this->input->post('endDate');

    	$searchArray = array();

    	if ($quarter == 1) {
    		$searchArray[] = "pu.quarter = 1";
    	} else if ($quarter == 2) {
    		$searchArray[] = "pu.quarter = 2";
    	} else if ($quarter == 3) {
    		$searchArray[] = "pu.quarter = 3";
    	} else if ($quarter == 4) {
    		$searchArray[] = "pu.quarter = 4";
    	}
    	$where = implode(" and ", $searchArray);

    	$plan_list = $this->Mportfolio->getPlanChart($where);
    	$values = array();
    	$quarterList = array('1' => 1, '2' => 2, '3' => 3, '4' => 4);
    	for ($i = 1; $i <= count($quarterList); $i++) {
    		foreach ($plan_list as $key => $value) {
    			$values[$i]['productName'] = 'Q' . $i;
    			if ($i == $value['pu_quarter'] || $i == $value['pp_quarter']) {
    				if (array_key_exists($i, $values)) {
    					$values[$i]['price'] = (int) $value['count_id'];
    				} else {
    					$values[$i]['price'] = $values[$i] + $value['count_id'];
    				}
    			}
    		}
    	}

    	$data['div_id'] = 'chartContainer_' . $id;
    	$data['chart_list'] = array_values($values);
    	$this->load->vars($data);
    	$this->load->view('portfolio/chart_d3');
    }

