        // $quarter = $this->input->post('quarter');
    	$startDate = $this->input->post('start_date');
    	$endDate = $this->input->post('end_date');

    	$searchArray = array();
    	$month_val = '';

        //     if ($quarter == 1) {
        //      $month_val = $searchArray[] = "MONTH(CD.created_at) IN (4,5,6)";
        //  } else if ($quarter == 2) {
