    public function allRevenue() {
    	$partner_id = $this->session->userdata('partner_id');
    	$data['fin_year'] = $this->Mportfolio->getAllFinancialYear($partner_id);
    	$f_year = date('Y');
    	foreach ($data['fin_year'] as $fy) {
    		if ($fy['status'] == 1) {
    			$f_year = $fy['fin_year'];
    		}
    	}
    	$findQuarter = $this->allQuarter();

    	$q1 = $this->quarter1();
    	$q2 = $this->quarter2();
    	$q3 = $this->quarter3();
    	$q4 = $this->quarter4();

    	$q1_val = $q2_val = $q3_val = $q4_val = 0;

    	$q1_key = array_keys($q1);
    	$q2_key = array_keys($q2);
    	$q3_key = array_keys($q3);
    	$q4_key = array_keys($q4);

    	$a1_val = $a2_val = $a3_val = $a4_val = 0;

    	$type = $this->input->post('type');
    	$from_quarter = $this->input->post('f_quarter');
    	$to_quarter = $this->input->post('t_quarter');
    	$from_year = $this->input->post('f_year');
    	$to_year = $this->input->post('t_year');
    	$start_date = $this->input->post('start_date');
    	$end_date = $this->input->post('end_date');

    	$search_array = $last_target = array();

    	if ($type == 1) {
    		$start_year = explode(',', $start_date);
    		$end_year = explode(',', $end_date);

    		$StartDate = $start_year[1] . '-' . date('m', strtotime($start_year[0])) . '-01';
    		$StopDate = $end_year[1] . '-' . date('m', strtotime($end_year[0])) . '-31';
    		$date_diff = $this->get_months($StartDate, $StopDate);

    		$cond = "financial_year >= $start_year[1] and financial_year <= $end_year[1]";
    		$monthly_target = $this->Mportfolio->getTargetRevenue('', $cond);
    		$monthly_actual = $this->Mportfolio->getActualRevenue('', $cond);
    		foreach ($date_diff as $keys => $values) {
    			$yearvalues = explode('-', $values);
    			foreach ($monthly_target as $key => $value) {
    				if ($yearvalues[1] == $value['financial_year']) {
    					$datavalues = json_decode($value['data'], TRUE);
    					if (array_key_exists($yearvalues[0], $datavalues)) {
    						$cost = str_replace(',', '', $datavalues[$yearvalues[0]]);
    						if (array_key_exists($values, $search_array)) {
    							$search_array[$values] = $search_array[$values] + $cost;
    						} else {
    							$search_array[$values] = $cost;
    						}
    					} else {
    						$search_array[$values] = 0;
    					}
    				}
    				$i++;
    			}
    		}

    		$m = 0;
    		foreach ($search_array as $k => $name) {
    			$last_target[$m]['name'] = $k;
    			$last_target[$m]['target'] = $name;
    			$split = explode('-', $k);
    			$plan_month = date('n', strtotime($split[0]));
    			$split_year = $split[1];

    			$new_fy = array_filter($monthly_actual, function ($var) use ($split_year) {
    				return ($var['financial_year'] == $split_year);
    			});

    			$new_m = array_filter($new_fy, function ($var) use ($plan_month) {
    				return ($var['month'] == $plan_month);
    			});

    			$result = '';
    			if (count($new_m) > 0) {
    				foreach ($new_m as $key => $value) {
    					if (is_array($value)) {
    						if ($result['month'] == $value['month']) {
    							$actual_cost = str_replace(',', '', $value['revenue']);
    							$rev_cost = str_replace(',', '', $result['revenue']);
    							$last_target[$m]['actual'] = $rev_cost + $actual_cost;
    						} else {
    							$last_target[$m]['actual'] = str_replace(',', '', $value['revenue']);
    						}
    						$result = $value;
    					} else {
    						$result[$key] = $value;
    					}
    				}
    			} else {
    				$last_target[$m]['actual'] = 0;
    			}
    			$m++;
    		}
    	} else if ($type == 2) {
    		if ($from_quarter == 1) {
    			$start_month = reset($q1);
    		} else if ($from_quarter == 2) {
    			$start_month = reset($q2);
    		} else if ($from_quarter == 3) {
    			$start_month = reset($q3);
    		} else if ($from_quarter == 4) {
    			$start_month = reset($q4);
    		}

    		if ($to_quarter == 1) {
    			$end_month = end($q1);
    		} else if ($to_quarter == 2) {
    			$end_month = end($q2);
    		} else if ($to_quarter == 3) {
    			$end_month = end($q3);
    		} else if ($to_quarter == 4) {
    			$end_month = end($q4);
    		}

    		$q_StartDate = $from_year . '-' . date('m', strtotime($start_month)) . '-01';
    		$q_StopDate = $to_year . '-' . date('m', strtotime($end_month)) . '-31';
    		$date_diff = $this->get_months($q_StartDate, $q_StopDate);

    		$cond = "financial_year >= $from_year and financial_year <= $to_year";
    		$monthly_target = $this->Mportfolio->getTargetRevenue('', $cond);
    		$monthly_actual = $this->Mportfolio->getActualRevenue('', $cond);
    		foreach ($date_diff as $keys => $values) {
    			$yearvalues = explode('-', $values);
    			foreach ($monthly_target as $key => $value) {
    				if ($yearvalues[1] == $value['financial_year']) {
    					$datavalues = json_decode($value['data'], TRUE);
    					if (array_key_exists($yearvalues[0], $datavalues)) {
    						$cost = str_replace(',', '', $datavalues[$yearvalues[0]]);
    						if (array_key_exists($values, $search_array)) {
    							$search_array[$values] = $search_array[$values] + $cost;
    						} else {
    							$search_array[$values] = $cost;
    						}
    					} else {
    						$search_array[$values] = 0;
    					}
    				}
    				$i++;
    			}
    		}

    		$m = 0;
    		foreach ($search_array as $k => $name) {
                // $fetch_target[$m]['name'] = $k;
    			$split = explode('-', $k);
    			$split_year = $split[1];
    			$axis_name = array_search($split[0], $findQuarter);
    			if ($axis_name == 'Q4') {
    				$q_year = $split_year - 1;
    			} else {
    				$q_year = $split_year;
    			}
    			$fetch_target[$m]['name'] = $axis_name . '-' . $q_year;
    			$fetch_target[$m]['target'] = $name;
    			$plan_month = date('n', strtotime($split[0]));

    			$new_fy = array_filter($monthly_actual, function ($var) use ($split_year) {
    				return ($var['financial_year'] == $split_year);
    			});

    			$new_m = array_filter($new_fy, function ($var) use ($plan_month) {
    				return ($var['month'] == $plan_month);
    			});

    			$result = '';
    			if (count($new_m) > 0) {
    				foreach ($new_m as $key => $value) {
    					if (is_array($value)) {
    						if ($result['month'] == $value['month']) {
    							$actual_cost = str_replace(',', '', $value['revenue']);
    							$rev_cost = str_replace(',', '', $result['revenue']);
    							$fetch_target[$m]['actual'] = $rev_cost + $actual_cost;
    						} else {
    							$fetch_target[$m]['actual'] = str_replace(',', '', $value['revenue']);
    						}
    						$result = $value;
    					} else {
    						$result[$key] = $value;
    					}
    				}
    			} else {
    				$fetch_target[$m]['actual'] = 0;
    			}
    			$m++;
    		}

    		$last_target = array();
    		$quarter_group = array_chunk($fetch_target, 3);

    		for ($q = 0; $q <= count($quarter_group); $q++) {
    			foreach ($quarter_group[$q] as $value) {
    				$inc = $q + 1;
    				$last_target[$q]['name'] = $value['name'];
    				$last_target[$q]['target'] += $value['target'];
    				$last_target[$q]['actual'] += $value['actual'];
    			}
    		}
    	} else {
    		$revenue_target = $this->Mportfolio->getTargetRevenue($f_year);
    		if (count($revenue_target) > 0) {
    			foreach ($revenue_target as $target) {
    				$get_data = json_decode($target['data']);
    				foreach ($get_data as $key => $value) {
    					if (in_array($key, $q1)) {
    						$q1_val += str_replace(',', '', $value);
    						$last_target[0]['name'] = 'Q1';
    						$last_target[0]['target'] = $q1_val;
    						$last_target[0]['actual'] = '0';
    					}
    					if (in_array($key, $q2)) {
    						$q2_val += str_replace(',', '', $value);
    						$last_target[1]['name'] = 'Q2';
    						$last_target[1]['target'] = $q2_val;
    						$last_target[1]['actual'] = '0';
    					}
    					if (in_array($key, $q3)) {
    						$q3_val += str_replace(',', '', $value);
    						$last_target[2]['name'] = 'Q3';
    						$last_target[2]['target'] = $q3_val;
    						$last_target[2]['actual'] = '0';
    					}
    					if (in_array($key, $q4)) {
    						$q4_val += str_replace(',', '', $value);
    						$last_target[3]['name'] = 'Q4';
    						$last_target[3]['target'] = $q4_val;
    						$last_target[3]['actual'] = '0';
    					}
    				}
    			}
    		}

    		$annual_target = $q1_val + $q2_val + $q3_val + $q4_val;
    		$last_target[4]['name'] = 'Annual';
    		$last_target[4]['target'] = $annual_target;

    		$revenue_actual = $this->Mportfolio->getActualRevenue($f_year);
    		if (count($revenue_actual) > 0) {
    			foreach ($revenue_actual as $actual) {
    				if (in_array($actual['month'], $q1_key)) {
    					$a1_val += str_replace(',', '', $actual['revenue']);
    					$last_target[0]['actual'] = $a1_val;
    				}
    				if (in_array($actual['month'], $q2_key)) {
    					$a2_val += str_replace(',', '', $actual['revenue']);
    					$last_target[1]['actual'] = $a2_val;
    				}
    				if (in_array($actual['month'], $q3_key)) {
    					$a3_val += str_replace(',', '', $actual['revenue']);
    					$last_target[2]['actual'] = $a3_val;
    				}
    				if (in_array($actual['month'], $q4_key)) {
    					$a4_val += str_replace(',', '', $actual['revenue']);
    					$last_target[3]['actual'] = $a4_val;
    				}
    			}
    		}

    		$annual_acheive = $a1_val + $a2_val + $a3_val + $a4_val;
    		$last_target[4]['actual'] = $annual_acheive;
    	}

    	$id = $this->input->post('id');
    	$data['div_id'] = 'revenueDiv_' . $id;
    	$data['target_list'] = json_encode($last_target);
    	$this->load->vars($data);
    	$this->load->view('portfolio/dashboard_chart/allRevenue_HC');
    }

