    public function getConversationData() {
//        if ($this->input->post('sector_id') != '')
    	$sector_id = $this->input->post('sector_id');

    	$data['financial_year'] = $current_fy = $this->input->post('fin_year');
    	$end_year = current_FYendYear($this->session->userdata('partner_id'));
    	$data['module_id'] = $this->input->post('module_id');
    	$data['partner_id'] = $this->input->post('partner_id');
    	$data['page_id'] = 2;
    	$data['status'] = 1;

    	$get_month = $this->month();
    	$q1_first = date('m', strtotime($get_month[0]));
    	$q1_end = date('m', strtotime($get_month[2]));
    	$q2_first = date('m', strtotime($get_month[3]));
    	$q2_end = date('m', strtotime($get_month[5]));
    	$q3_first = date('m', strtotime($get_month[6]));
    	$q3_end = date('m', strtotime($get_month[8]));
    	$q4_first = date('m', strtotime($get_month[9]));
    	$q4_end = date('m', strtotime($get_month[11]));

    	$q1_end_date = date("t", strtotime($q1_end));
    	$q2_end_date = date("t", strtotime($q2_end));
    	$q3_end_date = date("t", strtotime($q3_end));
    	$q4_end_date = date("t", strtotime($q4_end));

    	$quarter = $this->input->post('quarter');
    	if ($quarter == '1') {
    		$q_cond = "created_at BETWEEN '$current_fy-$q1_first-01' AND '$current_fy-$q1_end-$q1_end_date'";
    	} else if ($quarter == '2') {
    		$q_cond = "created_at BETWEEN '$current_fy-$q2_first-01' AND '$current_fy-$q2_end-$q2_end_date'";
    	} else if ($quarter == '3') {
    		$q_cond = "created_at BETWEEN '$current_fy-$q3_first-01' AND '$current_fy-$q3_end-$q3_end_date'";
    	} else if ($quarter == '4') {
    		$q_cond = "created_at BETWEEN '$end_year-$q4_first-01' AND '$end_year-$q4_end-$q4_end_date'";
    	} else {
    		$q_cond = "";
    	}

    	$result['conversation'] = $this->Mportfolio->getConversationDetails($data, $sector_id, $q_cond);

    	$this->load->vars($result);
    	$this->load->view('portfolio/chart_conversation_data');
    }

    public function getConversationData_old() {
    	if ($this->input->post('inv_id') != '')
    		$data['inv_id'] = $this->input->post('inv_id');

    	$result['chat_sector'] = $sector_id = $this->input->post('sector_id');
    	$result['chart_fyear'] = $data['financial_year'] = $this->input->post('fin_year');
    	$result['chat_module_id'] = $data['module_id'] = $this->input->post('module_id');


    	if (($_POST['page_id'] == 1 && ($_POST['module_id'] == 10 || $_POST['module_id'] == 11 || $_POST['module_id'] == 12)) || $_POST['page_id'] == 2)
    		$data['sector_id'] = isset($sector_id) && $sector_id != '' ? $sector_id : 0;

    	$data['page_id'] = 2;
    	$data['partner_id'] = $this->input->post('partner_id');
    	$start = 0;
    	$limit = 5;
    	$result['conversation'] = $this->Mportfolio->getConversationDetails($data, $limit, $start);

    	$this->load->vars($result);
    	$this->load->view('portfolio/chart_conversation_form');
    }

    public function addChartConversation() {
    	$data = array();
    	$data['inv_id'] = $option['inv_id'] = isset($_POST['innovation_id']) && $_POST['innovation_id'] != '' ? $_POST['innovation_id'] : 0;
    	$data['sector_id'] = isset($_POST['chart_sector']) && $_POST['chart_sector'] != '' ? $_POST['chart_sector'] : 0;
    	$data['financial_year'] = $option['financial_year'] = $current_fy = $this->input->post('chat_finYear');
    	$data['module_id'] = $option['module_id'] = $this->input->post('module_id');
    	$data['partner_id'] = $option['partner_id'] = $this->session->userdata('partner_id');
    	$data['page_id'] = $option['page_id'] = '2';
    	$data['emp_id'] = $this->session->userdata('emp_number');
    	$data['emp_name'] = $this->session->userdata('emp_name');
    	$data['comments'] = $this->db->escape_str($_POST['txt_description']);
    	$data['created_by'] = $this->session->userdata('emp_number');
    	$data['created_at'] = date("Y-m-d H:i:s");

    	$sector_id = $_POST['chart_sector'];
    	$quarter = $this->input->post('chat_quarter');
    	$end_year = current_FYendYear($this->session->userdata('partner_id'));

    	$get_month = $this->month();
    	$q1_first = date('m', strtotime($get_month[0]));
    	$q1_end = date('m', strtotime($get_month[2]));
    	$q2_first = date('m', strtotime($get_month[3]));
    	$q2_end = date('m', strtotime($get_month[5]));
    	$q3_first = date('m', strtotime($get_month[6]));
    	$q3_end = date('m', strtotime($get_month[8]));
    	$q4_first = date('m', strtotime($get_month[9]));
    	$q4_end = date('m', strtotime($get_month[11]));

    	$q1_end_date = date("t", strtotime($q1_end));
    	$q2_end_date = date("t", strtotime($q2_end));
    	$q3_end_date = date("t", strtotime($q3_end));
    	$q4_end_date = date("t", strtotime($q4_end));

    	if ($quarter == '1') {
    		$q_cond = "created_at BETWEEN '$current_fy-$q1_first-01' AND '$current_fy-$q1_end-$q1_end_date'";
    	} else if ($quarter == '2') {
    		$q_cond = "created_at BETWEEN '$current_fy-$q2_first-01' AND '$current_fy-$q2_end-$q2_end_date'";
    	} else if ($quarter == '3') {
    		$q_cond = "created_at BETWEEN '$current_fy-$q3_first-01' AND '$current_fy-$q3_end-$q3_end_date'";
    	} else if ($quarter == '4') {
    		$q_cond = "created_at BETWEEN '$end_year-$q4_first-01' AND '$end_year-$q4_end-$q4_end_date'";
    	} else {
    		$q_cond = "";
    	}

    	$query = $this->Mportfolio->insertPortfolioDetail('port_chart_conversation', $data);

    	if ($query) {
//            $result['conversation'] = $this->Mportfolio->getDetails('port_chart_conversation', $option);
    		$result['conversation'] = $this->Mportfolio->getConversationDetails($option, $sector_id, $q_cond);
    		$this->load->vars($result);
    		$chart_page = $this->load->view('portfolio/chart_conversation_data');
//            return $chart_page;
    	}
    }

