    public function insert_incComment() {
    	$data = array();
    	$data['page_id'] = "2";
    	$start_year = current_FYstartYear($this->session->userdata('partner_id'));
    	$data['financial_year'] = $start_year;
    	$data['sector_id'] = isset($_POST['chart_sector']) && $_POST['chart_sector'] != '' ? $_POST['chart_sector'] : 0;
    	$data['module_id'] = $this->input->post('module_id');
    	$data['partner_id'] = $this->session->userdata('partner_id');
    	$data['emp_id'] = $this->session->userdata('emp_number');
    	$data['emp_name'] = $this->session->userdata('emp_name');
    	$data['comments'] = $this->db->escape_str($_POST['comment']);
    	$data['created_by'] = $this->session->userdata('emp_number');
    	$data['created_at'] = date("Y-m-d H:i:s");

    	$query = $this->Mportfolio->insertPortfolioDetail('port_chart_conversation', $data);
    	if ($query) {
