		 public function getSector() { 
			
			$inv_id = $this->input->post('id');
			#echo $inv_id;die;
			$partner_id = $this->session->userdata('partner_id');
        	$data['sectors_values'] = $sectors_values = $this->Mincharge->getSectorNames($partner_id);
			$returnArr['response'] = '';
			$returnArr['response'] = '';
			$returnArr['selectedProgram_id'] = '';
			
			if($inv_id!=''){
				//'status'=>1,
				$portfolio_summary_year = $this->session->userdata('portfolio_summary_year');
				$programList  = $this->Mportfolio->get_all_data('port_business_year', array('year'=>$portfolio_summary_year,'inv_id'=>$inv_id));
				if(empty($programList)){
					$getPortBusinessSector  = $this->Mportfolio->get_all_data('port_business',array('inv_id'=>$inv_id));
					$selectedSector = $getPortBusinessSector[0]->sector;
					$sectorArray = explode(',', $selectedSector);
				}else{
					$selectedSector = $programList[0]->sector;
					$sectorArray = explode(',', $selectedSector);
				}
			}
			
			if (!empty($sectorArray)) {
				$returnArr['selectedProgram_id'] = $sectorArray;
			} 
			if (!empty($sectors_values)) {
				$returnArr['response'] = $sectors_values;
			}
			#echo'<pre>';print_r($usersList);die;
			echo json_encode($returnArr);
		}
		
		
